-- ===================================== src/nav.lua =====================================
do
    local module = (function()
-- nav.lua - Pursuit routing, obstacle steering, blacklists, escape routing, facing rig, point walking.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local NAV = S.NAV
local CFG = S.CFG
local LocalPlayer = S.LocalPlayer
local HZ = S.HZ
local getPlayerHitboxMetrics = S.getPlayerHitboxMetrics
local heavyDebug = S.heavyDebug
local evaluateHazardPenaltyAtPoint = S.evaluateHazardPenaltyAtPoint
local isPositionSafeFromDamageBricks = S.isPositionSafeFromDamageBricks
local heavyDebugThrottled = S.heavyDebugThrottled
local PathfindingService = S.PathfindingService
local setMovementState = S.setMovementState
local debugThrottleClocks = S.debugThrottleClocks
local Workspace = S.Workspace
local DEBUG_VERBOSE = S.DEBUG_VERBOSE
local STEER_PROBE_HEIGHTS = S.STEER_PROBE_HEIGHTS
local STEER_FAN_ANGLES = S.STEER_FAN_ANGLES
local DEBUG_NORMAL = S.DEBUG_NORMAL
local getVisualRoot = S.getVisualRoot
local getHazardMotion = S.getHazardMotion

local function clearRenderedPath()
    if NAV.nodesFolder then
        NAV.nodesFolder:Destroy()
        NAV.nodesFolder = nil
    end
end

-- Render High-Visibility Path
-- Node pool. Parts are reused in place rather than destroyed and rebuilt.
-- A 48-waypoint path with a marker every 1.5 studs is about 166 Parts, and the
-- old renderer recreated all of them on every recompute - several times a second
-- while stuck. That churn, not the drawing, was the stutter.
local NODE_MAIN_SIZE = Vector3.new(0.45, 0.45, 0.45)
local NODE_SUB_SIZE = Vector3.new(0.18, 0.18, 0.18)
local NODE_LIFT = Vector3.new(0, 0.2, 0)

local function applyNodePool(folder, entries)
    local children = folder:GetChildren()

    for i, entry in ipairs(entries) do
        local node = children[i]
        if not node then
            node = Instance.new("Part")
            node.Name = "PathNode"
            node.Anchored = true
            node.CanCollide = false
            node.CanQuery = false
            node.CanTouch = false
            node.CastShadow = false
            node.Material = Enum.Material.Neon
            node.Parent = folder
        end
        -- Only write what changed: a property write on an anchored part is a
        -- physics/replication touch, and most of a re-rendered route is the same.
        if node.Position ~= entry.position then node.Position = entry.position end
        if node.Size ~= entry.size then node.Size = entry.size end
        if node.Color ~= entry.color then node.Color = entry.color end
    end

    for i = #entries + 1, #children do
        children[i]:Destroy()
    end
end

local function renderCurrentPath()
    if not RT.renderPathEnabled or #NAV.waypoints == 0 then
        clearRenderedPath()
        return
    end

    if not NAV.nodesFolder or not NAV.nodesFolder.Parent then
        NAV.nodesFolder = Instance.new("Folder")
        NAV.nodesFolder.Name = "PursuitPathNodes"
        NAV.nodesFolder.Parent = getVisualRoot()
    end

    local entries = {}

    for index, waypoint in ipairs(NAV.waypoints) do
        table.insert(entries, {
            position = waypoint.Position + NODE_LIFT,
            size = NODE_MAIN_SIZE,
            color = CFG.colorPursuit,
        })
    end

    -- Fill the remaining budget with connecting dots, spaced to span the whole
    -- path. A long route now draws a sparser line instead of an unbounded one.
    local budget = CFG.pathNodeBudget - #entries
    if budget > 0 then
        local segments = {}
        local totalLength = 0
        for index = 1, #NAV.waypoints - 1 do
            local from = NAV.waypoints[index].Position
            local to = NAV.waypoints[index + 1].Position
            local length = (to - from).Magnitude
            if length > 0.01 then
                table.insert(segments, { from = from, to = to, length = length })
                totalLength = totalLength + length
            end
        end

        if totalLength > 0 then
            local spacing = math.max(1.5, totalLength / budget)
            for _, segment in ipairs(segments) do
                local count = math.floor(segment.length / spacing)
                for i = 1, count do
                    table.insert(entries, {
                        position = segment.from:Lerp(segment.to, i / (count + 1)) + NODE_LIFT,
                        size = NODE_SUB_SIZE,
                        color = Color3.fromRGB(255, 255, 255),
                    })
                end
            end
        end
    end

    applyNodePool(NAV.nodesFolder, entries)
end

local function resetPursuitPath()
    if NAV.blockedConnection then
        NAV.blockedConnection:Disconnect()
        NAV.blockedConnection = nil
    end
    NAV.waypoints = {}
    NAV.index = 1
    NAV.enemy = nil
    NAV.lastTarget = nil
    NAV.lastComputeTime = -math.huge
    NAV.needsRecompute = false
    NAV.computing = false
    NAV.progressPosition = nil
    NAV.progressTime = os.clock()
    NAV.lastIssuedMove = nil
    NAV.routeIsDirect = false
    NAV.directProgressPosition = nil
    NAV.directProgressTime = os.clock()
    NAV.stallAnchor = nil
    NAV.stallTime = os.clock()
    NAV.steerAngle = nil
    -- Blacklisted headings are intentionally kept across a reset: the walls that
    -- caused them are still there. They expire on their own timer.
    clearRenderedPath()
end

-- Every instance this script spawns into the world must be invisible to its own
-- raycasts, or the visualisers block the paths they are drawn to illustrate.
local function getRaycastExclusions(enemy)
    local exclusions = {}
    if LocalPlayer.Character then table.insert(exclusions, LocalPlayer.Character) end
    if enemy then table.insert(exclusions, enemy) end
    -- Every marker this script draws lives under one folder (2.1.0).
    if RT.visualRoot then table.insert(exclusions, RT.visualRoot) end
    return exclusions
end

local function projectToGround(position, enemy)
    local exclusions = getRaycastExclusions(enemy)

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = exclusions
    params.IgnoreWater = false

    local result = Workspace:Raycast(
        Vector3.new(position.X, position.Y + 6, position.Z),
        Vector3.new(0, -40, 0),
        params
    )
    return result and (result.Position + Vector3.new(0, 0.1, 0)) or position
end

-- Reused across calls so the clearance test allocates nothing per candidate.
local SEGMENT_PROBE_HEIGHT = Vector3.new(0, 2.8, 0)
local SEGMENT_SIDE_OFFSETS = { 0, 0, 0 }

local function isPathSegmentClear(fromPosition, toPosition, enemy)
    local flatDelta = Vector3.new(toPosition.X - fromPosition.X, 0, toPosition.Z - fromPosition.Z)
    local distance = flatDelta.Magnitude
    if distance < 0.1 then return true end

    local exclusions = getRaycastExclusions(enemy)

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = exclusions
    params.IgnoreWater = true

    local direction = flatDelta.Unit
    local side = Vector3.new(-direction.Z, 0, direction.X)
    local _, playerRadius = getPlayerHitboxMetrics()
    local clearanceOffset = math.max(CFG.wallPadding, playerRadius + 0.6)

    -- Was a 3x3 sweep, 9 casts per candidate, with both loop tables reallocated
    -- on every call. One chest-height pass across three lateral offsets is enough
    -- of a prefilter now that the navmesh makes the final reachability call.
    local sideOffsets = SEGMENT_SIDE_OFFSETS
    sideOffsets[2] = clearanceOffset
    sideOffsets[3] = -clearanceOffset

    for i = 1, 3 do
        local origin = fromPosition + SEGMENT_PROBE_HEIGHT + (side * sideOffsets[i])
        local destination = toPosition + SEGMENT_PROBE_HEIGHT + (side * sideOffsets[i])
        local hit = Workspace:Raycast(origin, destination - origin, params)
        if hit and hit.Instance and hit.Instance.CanCollide then
            return false
        end
    end

    local groundCheck = Workspace:Raycast(
        toPosition + Vector3.new(0, 3.0, 0),
        Vector3.new(0, -12, 0),
        params
    )
    if not groundCheck then
        return false
    end

    return true
end

local function pruneBlockedAreas(now)
    for i = #NAV.blockedAreas, 1, -1 do
        if now >= NAV.blockedAreas[i].expires then
            table.remove(NAV.blockedAreas, i)
        end
    end
end

-- Planar, like the rest of the avoidance maths.
local function isInsideBlockedArea(position)
    local now = os.clock()
    for _, area in ipairs(NAV.blockedAreas) do
        if now < area.expires then
            local offset = Vector2.new(position.X - area.position.X, position.Z - area.position.Z)
            if offset.Magnitude <= area.radius then
                return true
            end
        end
    end
    return false
end

-- Re-trapping in the same place grows the area rather than stacking overlapping
-- entries, so a wide dead-end is eventually covered by one region.
local function blockArea(position, now)
    for _, area in ipairs(NAV.blockedAreas) do
        local offset = Vector2.new(position.X - area.position.X, position.Z - area.position.Z)
        if offset.Magnitude <= area.radius then
            area.expires = now + CFG.stuckAreaLife
            area.radius = math.min(area.radius + 2.0, CFG.stuckAreaRadius * 2.5)
            heavyDebug("Stuck", string.format(
                "Trapped again in a known bad area; radius grown to %.1f.", area.radius))
            return
        end
    end

    table.insert(NAV.blockedAreas, {
        position = position,
        radius = CFG.stuckAreaRadius,
        expires = now + CFG.stuckAreaLife,
    })
    heavyDebug("Stuck", string.format(
        "Stood still %.1fs without dodging at (%.0f, %.0f). Area blacklisted for %.0fs.",
        CFG.stuckAreaTime, position.X, position.Z, CFG.stuckAreaLife))
end

local function buildEscapeCandidates(rootPos, targetPos, enemy)
    local candidates = {}
    local _, playerRadius = getPlayerHitboxMetrics()

    for _, part in ipairs(HZ.detected) do
        if part.Parent then
            local localPos = part.CFrame:PointToObjectSpace(rootPos)
            local size = part.Size
            local halfSize = size * 0.5
            local pushDist = CFG.damageBrickClearance + playerRadius + 1.0

            local escapeLocal
            if halfSize.X < halfSize.Z then
                local xDir = localPos.X >= 0 and 1 or -1
                escapeLocal = Vector3.new(xDir * (halfSize.X + pushDist), 0, math.clamp(localPos.Z, -halfSize.Z, halfSize.Z))
            else
                local zDir = localPos.Z >= 0 and 1 or -1
                escapeLocal = Vector3.new(math.clamp(localPos.X, -halfSize.X, halfSize.X), 0, zDir * (halfSize.Z + pushDist))
            end

            local edgeWorld = projectToGround(part.CFrame:PointToWorldSpace(escapeLocal), enemy)

            if isPathSegmentClear(rootPos, edgeWorld, enemy) then
                local penalty = evaluateHazardPenaltyAtPoint(edgeWorld)
                local isSafe = isPositionSafeFromDamageBricks(edgeWorld, 0.5)
                local distToTarget = Vector2.new(edgeWorld.X - targetPos.X, edgeWorld.Z - targetPos.Z).Magnitude
                table.insert(candidates, {
                    Position = edgeWorld,
                    Distance = (edgeWorld - rootPos).Magnitude,
                    DistToTarget = distToTarget,
                    Penalty = penalty,
                    IsSafe = isSafe
                })
            end
        end
    end

    -- Moving hazards (2.3.0): the best dodge from a projectile is sideways out
    -- of its line, so each one contributes two candidates perpendicular to its
    -- travel. The penalty and safety tests already see the swept strip, so these
    -- rank themselves.
    for _, part in ipairs(HZ.detected) do
        local velocity = part.Parent and getHazardMotion(part)
        if velocity then
            local flat = Vector3.new(velocity.X, 0, velocity.Z)
            if flat.Magnitude > 0.1 then
                local side = Vector3.new(-flat.Unit.Z, 0, flat.Unit.X)
                local reach = CFG.preemptiveClearance + playerRadius + 4.0
                for sign = -1, 1, 2 do
                    local candidate = projectToGround(rootPos + side * (sign * reach), enemy)
                    if isPathSegmentClear(rootPos, candidate, enemy) then
                        table.insert(candidates, {
                            Position = candidate,
                            Distance = (candidate - rootPos).Magnitude,
                            DistToTarget = Vector2.new(candidate.X - targetPos.X, candidate.Z - targetPos.Z).Magnitude,
                            Penalty = evaluateHazardPenaltyAtPoint(candidate),
                            IsSafe = isPositionSafeFromDamageBricks(candidate, 0.5),
                        })
                    end
                end
            end
        end
    end

    -- Coarser fan: 4x10 instead of 6x16. The old grid produced 96 candidates and
    -- each ran a 9-ray clearance test, roughly 900 raycasts per escape. Navmesh
    -- validation now decides reachability, so this only has to rank plausibly.
    local distances = {3, 6, 11, 18}
    local angles = {0, 25, -25, 55, -55, 90, -90, 135, -135, 180}

    for _, dist in ipairs(distances) do
        for _, angle in ipairs(angles) do
            local rad = math.rad(angle)
            local offset = Vector3.new(math.sin(rad) * dist, 0, math.cos(rad) * dist)
            local candidate = projectToGround(Vector3.new(rootPos.X + offset.X, rootPos.Y, rootPos.Z + offset.Z), enemy)

            if isPathSegmentClear(rootPos, candidate, enemy) then
                local penalty = evaluateHazardPenaltyAtPoint(candidate)
                local isSafe = isPositionSafeFromDamageBricks(candidate, 0.5)
                local distToTarget = Vector2.new(candidate.X - targetPos.X, candidate.Z - targetPos.Z).Magnitude
                table.insert(candidates, {
                    Position = candidate,
                    Distance = dist,
                    DistToTarget = distToTarget,
                    Penalty = penalty,
                    IsSafe = isSafe
                })
            end
        end
    end

    for _, candidate in ipairs(candidates) do
        candidate.InBadArea = isInsideBlockedArea(candidate.Position)
    end

    table.sort(candidates, function(a, b)
        if a.IsSafe ~= b.IsSafe then
            return a.IsSafe
        end
        -- A spot that already trapped us is a poor place to flee to, but still
        -- better than staying in the damage, so it sorts last rather than out.
        if a.InBadArea ~= b.InBadArea then
            return b.InBadArea
        end
        if math.abs(a.Distance - b.Distance) > 1.0 then
            return a.Distance < b.Distance
        end
        return a.DistToTarget < b.DistToTarget
    end)

    return candidates
end

local function findStagingSafePoint(rootPos, targetPos, enemy)
    local candidates = buildEscapeCandidates(rootPos, targetPos, enemy)
    return candidates[1] and candidates[1].Position or nil
end

local function clearEscapeNodes()
    if NAV.escapeNodesFolder then
        NAV.escapeNodesFolder:Destroy()
        NAV.escapeNodesFolder = nil
    end
end

local function clearEscapeRoute()
    NAV.escapeWaypoints = {}
    NAV.escapeIndex = 1
    NAV.escapeTarget = nil
    NAV.lastEscapeTime = -math.huge
    clearEscapeNodes()
end

local function renderEscapeRoute()
    if not RT.renderPathEnabled or #NAV.escapeWaypoints == 0 then
        clearEscapeNodes()
        return
    end

    if not NAV.escapeNodesFolder or not NAV.escapeNodesFolder.Parent then
        NAV.escapeNodesFolder = Instance.new("Folder")
        NAV.escapeNodesFolder.Name = "EscapeNodes"
        NAV.escapeNodesFolder.Parent = getVisualRoot()
    end

    local entries = {}
    for _, waypoint in ipairs(NAV.escapeWaypoints) do
        table.insert(entries, {
            position = waypoint.Position + Vector3.new(0, 0.25, 0),
            size = Vector3.new(0.5, 0.5, 0.5),
            color = CFG.colorEscape,
        })
    end

    applyNodePool(NAV.escapeNodesFolder, entries)
end

-- Picks an escape point the character can actually walk to. Ranked candidates are
-- checked against the real navmesh in order, because a raycast-clear straight line
-- still walks into concave geometry, which is what was getting the bot stuck.
-- Runs off the Heartbeat because ComputeAsync yields.
local function resolveEscapeRoute(rootPos, targetPos, enemy)
    if NAV.computingEscape then return end
    NAV.computingEscape = true

    local ok, err = xpcall(function()
        local candidates = buildEscapeCandidates(rootPos, targetPos, enemy)
        if #candidates == 0 then
            heavyDebugThrottled("escape_none", 1.0, "Escape", "No escape candidates produced.")
            return
        end

        -- No point validating against a navmesh that cannot answer.
        if os.clock() < NAV.navmeshDeadUntil then
            NAV.escapeWaypoints = {
                { Position = candidates[1].Position, Action = Enum.PathWaypointAction.Walk }
            }
            NAV.escapeIndex = 1
            NAV.escapeTarget = candidates[1].Position
            heavyDebugThrottled("escape_direct", 3.0, "Escape",
                "Navmesh unusable here; stepping straight to the best-ranked safe point.")
            renderEscapeRoute()
            return
        end

        local budget = math.min(#candidates, CFG.escapeValidationBudget)
        for i = 1, budget do
            local candidate = candidates[i]
            local path = PathfindingService:CreatePath({
                AgentRadius = CFG.wallPadding,
                AgentHeight = 4.5,
                AgentCanJump = true,
                AgentCanClimb = false,
                WaypointSpacing = 4
            })

            local computed = pcall(function()
                path:ComputeAsync(rootPos, candidate.Position)
            end)

            if computed and path.Status == Enum.PathStatus.Success then
                local waypoints = path:GetWaypoints()
                if #waypoints > 1 then
                    NAV.escapeWaypoints = waypoints
                    NAV.escapeIndex = 2
                    NAV.escapeTarget = candidate.Position
                    heavyDebug("Escape", string.format(
                        "Reachable escape found: candidate %d/%d, %.1f studs out, %d waypoints.",
                        i, budget, candidate.Distance, #waypoints))
                    renderEscapeRoute()
                    return
                end
            end

            heavyDebug("Escape", string.format(
                "Candidate %d/%d unreachable (status %s). Trying next.",
                i, budget, tostring(path.Status)), DEBUG_VERBOSE)
        end

        -- Nothing validated. Walk at the best-ranked point directly rather than
        -- standing in the damage, but say so; this is the case that can snag.
        NAV.escapeWaypoints = {
            { Position = candidates[1].Position, Action = Enum.PathWaypointAction.Walk }
        }
        NAV.escapeIndex = 1
        NAV.escapeTarget = candidates[1].Position
        heavyDebugThrottled("escape_unvalidated", 1.0, "Escape", string.format(
            "No candidate of %d passed navmesh validation. Falling back to straight-line escape.", budget))
        renderEscapeRoute()
    end, debug.traceback)

    NAV.computingEscape = false

    if not ok then
        heavyDebugThrottled("escape_error", 1.0, "FATAL", "Escape resolver threw:\n" .. tostring(err))
    end
end

-- Advances along the validated escape path. Returns false when the route is spent.
local function followEscapeRoute(humanoid, root)
    while NAV.escapeIndex <= #NAV.escapeWaypoints do
        local waypoint = NAV.escapeWaypoints[NAV.escapeIndex]
        local delta = root.Position - waypoint.Position
        local horizontal = Vector3.new(delta.X, 0, delta.Z).Magnitude
        if horizontal > CFG.escapeWaypointAdvanceDistance then
            break
        end
        NAV.escapeIndex = NAV.escapeIndex + 1
    end

    local waypoint = NAV.escapeWaypoints[NAV.escapeIndex]
    if not waypoint then
        return false
    end

    if waypoint.Action == Enum.PathWaypointAction.Jump then
        humanoid.Jump = true
    end
    humanoid:MoveTo(waypoint.Position)
    setMovementState(string.format("ESCAPE wp %d/%d", NAV.escapeIndex, #NAV.escapeWaypoints))
    return true
end

-- Yaw-only orientation. Position is preserved and pitch/roll are left flat, so
-- this sets which way the character looks without moving or tipping it, and does
-- not fight Humanoid:MoveTo, which drives velocity rather than facing.
-- One Attachment + AlignOrientation, built once per character and reused. Rigid
-- so it snaps rather than easing, matching the previous behaviour.
local function ensureFacingRig(root)
    if NAV.faceAligner and NAV.faceAligner.Parent == root
        and NAV.faceAttachment and NAV.faceAttachment.Parent == root then
        return NAV.faceAligner
    end

    if NAV.faceAligner then NAV.faceAligner:Destroy() end
    if NAV.faceAttachment then NAV.faceAttachment:Destroy() end
    NAV.faceAligner, NAV.faceAttachment = nil, nil

    local built = pcall(function()
        local attachment = Instance.new("Attachment")
        attachment.Name = "DungeonFaceAttachment"
        attachment.Parent = root

        local aligner = Instance.new("AlignOrientation")
        aligner.Name = "DungeonFaceAligner"
        aligner.Mode = Enum.OrientationAlignmentMode.OneAttachment
        aligner.Attachment0 = attachment
        -- Not rigid. A rigid constraint snaps the body to the exact bearing every
        -- frame, and against a close, moving enemy that bearing swings several
        -- degrees per frame, so the character whipped back and forth - the
        -- stutter that survived the 1.16.0 facing rewrite. Easing with a high
        -- responsiveness still turns fast, but smoothly, without the whip.
        aligner.RigidityEnabled = false
        pcall(function()
            aligner.MaxTorque = CFG.faceMaxTorque
            aligner.Responsiveness = CFG.faceResponsiveness
        end)
        aligner.Enabled = false
        aligner.Parent = root

        NAV.faceAttachment = attachment
        NAV.faceAligner = aligner
    end)

    return built and NAV.faceAligner or nil
end

local function faceTowards(root, humanoid, targetPosition)
    local flat = Vector3.new(
        targetPosition.X - root.Position.X, 0, targetPosition.Z - root.Position.Z)
    if flat.Magnitude < 0.05 then return end

    local desired = flat.Unit
    local look = root.CFrame.LookVector

    -- Skip while already pointed close enough, roughly six degrees. Writing the
    -- CFrame is not free and there is no reason to do it every frame.
    if (look.X * desired.X) + (look.Z * desired.Z) > 0.995 then
        humanoid.AutoRotate = false
        return
    end

    humanoid.AutoRotate = false

    -- Prefer an AlignOrientation constraint. Writing CFrame moves the assembly,
    -- which forces a physics resolve and a replication update every time; even
    -- with the velocity carried across it showed up as stutter. The constraint
    -- only ever has a property set on it and never touches position at all.
    local aligner = ensureFacingRig(root)
    if aligner then
        aligner.CFrame = CFrame.new(Vector3.zero, desired)
        aligner.Enabled = true
        return
    end

    -- Fallback for clients without the constraint. Assigning CFrame resets the
    -- assembly's velocity, which pinned the character in place, so it is carried
    -- across the write and only the orientation changes.
    local linearVelocity = root.AssemblyLinearVelocity
    local angularVelocity = root.AssemblyAngularVelocity

    root.CFrame = CFrame.new(root.Position, root.Position + desired)

    root.AssemblyLinearVelocity = linearVelocity
    root.AssemblyAngularVelocity = angularVelocity
end

local function releaseFacing(humanoid)
    if NAV.faceAligner and NAV.faceAligner.Parent then
        NAV.faceAligner.Enabled = false
    end
    if humanoid then
        humanoid.AutoRotate = true
    end
end

local function destroyFacingRig()
    if NAV.faceAligner then NAV.faceAligner:Destroy() end
    if NAV.faceAttachment then NAV.faceAttachment:Destroy() end
    NAV.faceAligner, NAV.faceAttachment = nil, nil
end

local function getStandOffPosition(root, enemyRoot)
    local enemyPosition = enemyRoot.Position
    local offset = root.Position - enemyPosition
    local flatOffset = Vector3.new(offset.X, 0, offset.Z)
    local directionAway

    if flatOffset.Magnitude > 0.001 then
        directionAway = flatOffset.Unit
    else
        local look = enemyRoot.CFrame.LookVector
        local flatLook = Vector3.new(-look.X, 0, -look.Z)
        directionAway = flatLook.Magnitude > 0.001 and flatLook.Unit or Vector3.new(0, 0, 1)
    end

    return enemyPosition + (directionAway * math.max(CFG.safeDistance, 2))
end

-- Primary Wall-Aware Pathfinding Router with Debug Output
-- Walks a straight line to the target in short hops, each dropped onto the floor.
-- Short hops rather than one long MoveTo so the humanoid can follow stairs and
-- ramps, and so the stuck detector has intermediate progress to measure against.
local function buildDirectWalkRoute(fromPosition, toPosition, enemy)
    local flat = Vector3.new(toPosition.X - fromPosition.X, 0, toPosition.Z - fromPosition.Z)
    local distance = flat.Magnitude
    local waypoints = {}

    local steps = math.clamp(math.floor(distance / CFG.directWalkStepLength), 1, 24)
    for i = 1, steps do
        local alpha = i / steps
        local point = fromPosition:Lerp(toPosition, alpha)
        table.insert(waypoints, {
            Position = projectToGround(point, enemy),
            Action = Enum.PathWaypointAction.Walk,
        })
    end

    return waypoints
end

-- Rotates a flat direction around Y.
local function rotateFlatDirection(direction, degrees)
    local radians = math.rad(degrees)
    local cosine, sine = math.cos(radians), math.sin(radians)
    return Vector3.new(
        direction.X * cosine - direction.Z * sine,
        0,
        direction.X * sine + direction.Z * cosine
    )
end

-- Direct walking has no navmesh to route around geometry, so it steers itself:
-- probe straight at the goal, and if that is blocked, fan outwards until a clear
-- heading is found. Preferring the smallest deviation keeps it hugging the
-- intended direction rather than wandering off.
-- Returns the first SOLID hit along a ray.
--
-- Raycast reports whichever part it meets first, collidable or not. The steering
-- probe used to accept a heading whenever that first hit was non-collidable,
-- which silently ignored any wall standing behind a decoration or an effect
-- part. Dungeons are full of both, so the bot walked into walls occasionally and
-- for no visible reason. Non-collidable hits are now skipped through.
local function castSolid(origin, displacement, exclusions)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = exclusions
    params.IgnoreWater = true

    -- Newer clients can filter non-collidable geometry natively. Support is
    -- tested once at startup (core.lua); this used to be a pcall plus a closure
    -- on every single cast, dozens of times a frame while steering.
    if RT.respectCanCollide then
        params.RespectCanCollide = true
        return Workspace:Raycast(origin, displacement, params)
    end

    local ignored = table.clone(exclusions)
    for _ = 1, 8 do
        params.FilterDescendantsInstances = ignored
        local hit = Workspace:Raycast(origin, displacement, params)
        if not hit then return nil end
        if hit.Instance.CanCollide then return hit end
        table.insert(ignored, hit.Instance)
    end
    return nil
end

-- A single centre ray also missed anything the character's shoulders clip, and
-- anything below chest height such as a railing, so clearance is tested as a
-- crude capsule: two heights across the character's own width.
--
-- Returns how far the capsule stays clear along `heading`, capped at `length`,
-- and `length` when nothing is hit. The steerer used to ask only the yes/no
-- question "clear at the probe distance?" and take the first heading that passed;
-- measuring the distance instead lets it prefer the roomiest heading, so it runs
-- into open space rather than committing to whichever near-blocked direction
-- happened to clear the probe by a hair.
-- Feet height of the character: the root part sits HipHeight above the floor.
local function getFeetY(root)
    local humanoid = root.Parent and root.Parent:FindFirstChildWhichIsA("Humanoid")
    local hip = humanoid and humanoid.HipHeight or 2.0
    return root.Position.Y - root.Size.Y * 0.5 - hip
end

-- Does a probe hit actually block walking? (2.2.0)
--
-- This is why the bot stuck on "semi rough terrain": the shin-height probe sits
-- about 1.4 studs above the feet, so on any upward slope it hit the ramp itself
-- within a few studs and reported the heading blocked. Straight ahead was then
-- never "clear the whole way", the fan swung to whichever sideways heading was
-- roomier, and the bot ground along the foot of every incline. A hit only
-- counts now if it is wall-like: a surface facing up is floor or ramp, and a
-- lip no taller than a step (checked by looking DOWN from head height just past
-- the hit) is something the humanoid steps onto. Tall walls are still caught -
-- by the head-height probe, which is unaffected.
local function hitBlocksWalking(hit, heading, feetY, exclusions)
    if hit.Normal.Y >= CFG.walkableNormalY then return false end
    if hit.Position.Y - feetY > CFG.maxStepHeight then return true end
    local past = hit.Position + heading * 0.75
    local top = castSolid(Vector3.new(past.X, feetY + 4.6, past.Z), Vector3.new(0, -5.1, 0), exclusions)
    if not top then return false end           -- a lip with a drop behind it; falling is allowed
    return (top.Position.Y - feetY) > CFG.maxStepHeight
end

-- Reused across calls so the fan allocates nothing per heading.
local HEADING_LATERALS = { 0, 0, 0 }

local function headingClearDistance(root, heading, length, enemy, radius)
    local exclusions = getRaycastExclusions(enemy)
    local side = Vector3.new(-heading.Z, 0, heading.X)
    local displacement = heading * length
    local nearest = length
    local feetY = getFeetY(root)
    HEADING_LATERALS[2] = radius
    HEADING_LATERALS[3] = -radius

    for _, height in ipairs(STEER_PROBE_HEIGHTS) do
        for i = 1, 3 do
            local origin = root.Position + Vector3.new(0, height, 0) + (side * HEADING_LATERALS[i])
            local hit = castSolid(origin, displacement, exclusions)
            if hit and hitBlocksWalking(hit, heading, feetY, exclusions) then
                local d = (hit.Position - origin).Magnitude
                if d < nearest then nearest = d end
            end
        end
    end

    return nearest
end


local function pruneBlockedHeadings(now)
    for i = #NAV.blockedHeadings, 1, -1 do
        if now >= NAV.blockedHeadings[i].expires then
            table.remove(NAV.blockedHeadings, i)
        end
    end
end

-- Angle between two flat unit vectors, in degrees.
local function flatAngleBetween(a, b)
    return math.deg(math.acos(math.clamp(a:Dot(b), -1, 1)))
end

local function isHeadingBlocked(heading, now)
    for _, entry in ipairs(NAV.blockedHeadings) do
        if now < entry.expires and flatAngleBetween(heading, entry.direction) <= entry.arc then
            return true
        end
    end
    return false
end

-- Records a heading that produced no movement. Re-blocking the same direction
-- widens its arc and extends it, because a repeat offender is usually a wall
-- being clipped at a shallow angle rather than a one-off snag.
local function blockHeading(direction, now)
    local flat = Vector3.new(direction.X, 0, direction.Z)
    if flat.Magnitude < 0.01 then return end
    flat = flat.Unit

    for _, entry in ipairs(NAV.blockedHeadings) do
        if flatAngleBetween(flat, entry.direction) <= entry.arc then
            entry.expires = now + CFG.headingBlacklistTime
            entry.arc = math.min(entry.arc + CFG.headingBlacklistArcGrowth, CFG.headingBlacklistMaxArc)
            heavyDebug("Steering", string.format(
                "Heading still blocked; arc widened to %.0f degrees.", entry.arc))
            return
        end
    end

    table.insert(NAV.blockedHeadings, {
        direction = flat,
        arc = CFG.headingBlacklistArc,
        expires = now + CFG.headingBlacklistTime,
    })
    heavyDebug("Steering", string.format(
        "Blacklisted heading (%.2f, %.2f) for %.0fs after no movement.",
        flat.X, flat.Z, CFG.headingBlacklistTime))
end

local function steerTowards(root, goalPosition, enemy)
    local flat = Vector3.new(
        goalPosition.X - root.Position.X, 0, goalPosition.Z - root.Position.Z)
    local distance = flat.Magnitude
    if distance < 0.5 then return goalPosition end

    local direction = flat.Unit
    local probeLength = math.min(distance, CFG.steerProbeDistance)
    local _, playerRadius = getPlayerHitboxMetrics()
    local now = os.clock()

    -- Reuse the last decision for a moment. The fan is six rays per heading
    -- across up to eleven headings, and running all of it every frame was the
    -- second largest cost in direct mode. The answer changes slowly, and the
    -- stall detector is what catches a heading that has gone bad.
    if NAV.steerCache
        and (now - NAV.steerCacheTime) < CFG.steerRefreshInterval
        and NAV.steerCacheGoal
        and (NAV.steerCacheGoal - goalPosition).Magnitude < 4.0 then
        return NAV.steerCache, NAV.steerCacheAngle
    end

    pruneBlockedHeadings(now)

    -- Minimum room worth stepping into: a couple of body-widths plus a margin.
    -- Below this a heading is treated as blocked rather than "clear by a hair".
    local minClear = math.min(probeLength, playerRadius * 2 + CFG.steerOpennessMargin)

    local function commit(angle, grounded)
        if angle ~= NAV.steerAngle then
            NAV.steerAngle = angle
            NAV.steerTime = now
        end
        NAV.steerCache = grounded
        NAV.steerCacheAngle = angle
        NAV.steerCacheTime = now
        NAV.steerCacheGoal = goalPosition
    end

    -- Measures one heading. Returns the grounded destination and how open the
    -- heading is, or nil if it is blocked, blacklisted, off a ledge or inside a
    -- known-bad area.
    local function evaluate(angle, respectBlacklist)
        local heading = rotateFlatDirection(direction, angle)
        if respectBlacklist and isHeadingBlocked(heading, now) then return nil end
        local clear = headingClearDistance(root, heading, probeLength, enemy, playerRadius)
        if clear < minClear then return nil end
        -- Require floor at the destination so it does not steer off a ledge.
        local candidate = root.Position + (heading * math.min(clear, probeLength))
        local grounded = projectToGround(candidate, enemy)
        -- Asymmetric (2.2.0): a drop is fine - there is no fall damage to speak
        -- of and the drop is usually the way forward - but a climb has to be
        -- within a jump. The old symmetric 12-stud gate refused ledges down.
        local rise = grounded.Y - getFeetY(root)
        if rise >= CFG.maxClimbHeight or rise <= -CFG.maxDropHeight then return nil end
        if respectBlacklist and isInsideBlockedArea(grounded) then return nil end
        return grounded, clear
    end

    local openThreshold = probeLength - 0.5

    local function pick(respectBlacklist)
        -- Stay on the committed deviation while it is still genuinely roomy, so
        -- the steerer does not oscillate between two equally open headings and
        -- grind into the corner between them. It is dropped the moment it stops
        -- being open, which is what lets it peel away from a wall it is scraping.
        if NAV.steerAngle and (now - NAV.steerTime) < CFG.steerCommitTime then
            local grounded, clear = evaluate(NAV.steerAngle, respectBlacklist)
            if grounded and clear >= probeLength * 0.85 then
                commit(NAV.steerAngle, grounded)
                return grounded, NAV.steerAngle
            end
        end

        -- Walk the fan in increasing deviation and take the FIRST heading that is
        -- clear the whole way. In the open that is straight ahead on the first
        -- probe, so the common case is six rays and cheap - evaluating every
        -- heading each frame to rank openness was a real frame cost. Only when
        -- nothing is clear the whole way (a genuinely tight spot) do we fall back
        -- to the roomiest partial heading, which is what turns the bot into the
        -- open direction along a wall instead of grinding straight into it.
        local bestGrounded, bestAngle, bestClear
        for _, angle in ipairs(STEER_FAN_ANGLES) do
            local grounded, clear = evaluate(angle, respectBlacklist)
            if grounded then
                if clear >= openThreshold
                    and math.abs(angle) <= CFG.steerOpennessDeviationBudget then
                    commit(angle, grounded)
                    return grounded, angle
                end
                if not bestClear or clear > bestClear then
                    bestClear, bestGrounded, bestAngle = clear, grounded, angle
                end
            end
        end

        if bestGrounded then
            commit(bestAngle, bestGrounded)
            return bestGrounded, bestAngle
        end
        return nil
    end

    local target, angle = pick(true)
    if target then return target, angle end

    -- Nothing survived the blacklist. Retry ignoring it, since standing still is
    -- never better than trying a direction that failed a while ago. Skipped when
    -- the blacklist is empty, because that second sweep would be identical.
    if #NAV.blockedHeadings > 0 then
        heavyDebugThrottled("steer_allblocked", 3.0, "Steering",
            "No unblocked heading available; retrying without the blacklist.")
        target, angle = pick(false)
        if target then return target, angle end
    end

    NAV.steerAngle = nil
    return goalPosition, nil
end

-- Confirms whether the navmesh works *at all* from here, by pathing a few studs
-- forward. If even that fails the problem is the place, not the target, and
-- benching every enemy on the map would be the wrong conclusion.
local function probeNavmeshUsable(fromPosition, enemy)
    local probeTarget = projectToGround(
        fromPosition + Vector3.new(CFG.navmeshProbeDistance, 0, 0), enemy)

    local path = PathfindingService:CreatePath({
        AgentRadius = 1.0,
        AgentHeight = 4.5,
        AgentCanJump = true,
        AgentCanClimb = false,
        WaypointSpacing = 4
    })

    local ok = pcall(function()
        path:ComputeAsync(fromPosition, probeTarget)
    end)

    return ok and path.Status == Enum.PathStatus.Success
end


-- Commits a set of waypoints as the active pursuit route.
local function adoptPursuitRoute(waypoints, enemy, targetPosition, startIndex)
    NAV.waypoints = waypoints
    NAV.index = startIndex
    NAV.enemy = enemy
    NAV.lastTarget = targetPosition
    NAV.lastComputeTime = os.clock()
    NAV.lastIssuedMove = nil
    NAV.needsRecompute = false
    NAV.computing = false
    renderCurrentPath()
end

local function computePursuitPath(root, enemy, targetPosition)
    if NAV.computing then
        heavyDebug("Pathfinding", "Skipped: Already computing path in another thread.")
        return false
    end
    NAV.computing = true

    if NAV.blockedConnection then
        NAV.blockedConnection:Disconnect()
        NAV.blockedConnection = nil
    end

    local groundedStart = projectToGround(root.Position, enemy)
    local groundedTarget = projectToGround(targetPosition, enemy)
    local distanceToTarget = (groundedStart - groundedTarget).Magnitude
    heavyDebug("Pathfinding", string.format("Attempting path to %s. Distance: %.1f studs", enemy.Name, distanceToTarget))

    local inHazard = not isPositionSafeFromDamageBricks(groundedStart, 0.5)

    if inHazard then
        local stagingPointB = findStagingSafePoint(groundedStart, groundedTarget, enemy)
        if stagingPointB then
            heavyDebug("Pathfinding", "Phase 1: Executing Staging Escape Point B via Side-Escape.")
            local waypointsCombined = {
                {Position = groundedStart, Action = Enum.PathWaypointAction.Walk},
                {Position = stagingPointB, Action = Enum.PathWaypointAction.Walk}
            }

            local pathBC = PathfindingService:CreatePath({
                AgentRadius = CFG.wallPadding,
                AgentHeight = 4.5,
                AgentCanJump = true,
                AgentCanClimb = false,
                WaypointSpacing = 4
            })
            local successBC, _ = pcall(function()
                pathBC:ComputeAsync(stagingPointB, groundedTarget)
            end)

            if successBC and pathBC.Status == Enum.PathStatus.Success then
                local rawBC = pathBC:GetWaypoints()
                for i = 2, #rawBC do
                    table.insert(waypointsCombined, rawBC[i])
                end
            end

            NAV.waypoints = waypointsCombined
            NAV.index = 2
            NAV.enemy = enemy
            NAV.lastTarget = targetPosition
            NAV.lastComputeTime = os.clock()
            NAV.lastIssuedMove = nil
            NAV.needsRecompute = false
            NAV.computing = false
            renderCurrentPath()
            return true
        end
    end

    -- Navmesh already established as unusable here: skip the ladder entirely.
    -- Running four yielding ComputeAsync calls per attempt against a navmesh
    -- that cannot answer is what produced the log flood.
    if os.clock() < NAV.navmeshDeadUntil then
        heavyDebugThrottled("navmesh_direct", 3.0, "Pathfinding", string.format(
            "Navmesh unusable here; walking directly to %s (%.1f studs).",
            enemy.Name, distanceToTarget))
        adoptPursuitRoute(buildDirectWalkRoute(groundedStart, groundedTarget, enemy),
            enemy, targetPosition, 1)
        NAV.routeIsDirect = true
        return true
    end

    -- NoPath usually means one of three things: the agent is modelled too wide
    -- for a doorway, the standoff point landed off the navmesh, or the enemy is
    -- genuinely sealed off. The ladder below distinguishes them: shrink the
    -- agent first, then aim progressively shorter of the target so the bot at
    -- least closes distance and can re-path from somewhere better connected.
    local attempts = {
        { radius = CFG.wallPadding, fraction = 1.0, note = "full target, configured radius" },
        { radius = 1.0,             fraction = 1.0, note = "full target, slim radius" },
        { radius = 1.0,             fraction = 0.66, note = "two thirds of the way" },
        { radius = 1.0,             fraction = 0.33, note = "one third of the way" },
    }

    local path, rawWaypoints, lastStatus
    for index, attempt in ipairs(attempts) do
        local aimPoint = groundedTarget
        if attempt.fraction < 1.0 then
            aimPoint = projectToGround(groundedStart:Lerp(groundedTarget, attempt.fraction), enemy)
        end

        local candidatePath = PathfindingService:CreatePath({
            AgentRadius = attempt.radius,
            AgentHeight = 4.5,
            AgentCanJump = true,
            AgentCanClimb = false,
            WaypointSpacing = 4
        })

        local computed = pcall(function()
            candidatePath:ComputeAsync(groundedStart, aimPoint)
        end)

        lastStatus = candidatePath.Status

        if computed and candidatePath.Status == Enum.PathStatus.Success then
            local waypoints = candidatePath:GetWaypoints()
            if #waypoints > 1 then
                path = candidatePath
                rawWaypoints = waypoints
                if index > 1 then
                    heavyDebug("Pathfinding", string.format(
                        "Recovered on attempt %d/%d (%s).", index, #attempts, attempt.note))
                end
                break
            end
        end

        heavyDebug("Pathfinding", string.format("Attempt %d/%d failed (%s): %s",
            index, #attempts, attempt.note, tostring(candidatePath.Status)), DEBUG_VERBOSE)
    end

    if path then
        NAV.failureStreak = 0
        NAV.navmeshDeadUntil = -math.huge
        NAV.benched[enemy] = nil
        NAV.routeIsDirect = false
        adoptPursuitRoute(rawWaypoints, enemy, targetPosition, 2)

        NAV.blockedConnection = path.Blocked:Connect(function()
            heavyDebug("Pathfinding", "Path blocked event triggered. Forcing recompute.")
            NAV.needsRecompute = true
        end)

        return true
    end

    NAV.failureStreak = NAV.failureStreak + 1

    -- After repeated total failures, confirm the navmesh is dead here so future
    -- attempts can skip ComputeAsync entirely. This is now only an optimisation
    -- and a diagnostic; the fallback below no longer depends on its verdict.
    if NAV.failureStreak >= CFG.navmeshFailureThreshold then
        NAV.failureStreak = 0
        if not probeNavmeshUsable(groundedStart, enemy) then
            NAV.navmeshDeadUntil = os.clock() + CFG.navmeshRetestInterval
            table.clear(NAV.benched)
            heavyDebug("Pathfinding", string.format(
                "Navmesh cannot route even %.0f studs from here. Skipping ComputeAsync for %.0fs.",
                CFG.navmeshProbeDistance, CFG.navmeshRetestInterval))
        end
    end

    -- Always walk at the target. Benching here was the mistake: with no route to
    -- anything, every enemy got benched in turn and the bot cycled the whole map
    -- doing nothing. Heading in the right direction is strictly better than
    -- standing still, and often opens a route once the gap closes.
    -- An enemy is only benched later, by the stuck detector, if walking at it
    -- genuinely makes no progress.
    heavyDebugThrottled("path_direct", 2.0, "Pathfinding", string.format(
        "No navmesh route to %s (%s) at %.1f studs. Walking directly instead.",
        enemy.Name, tostring(lastStatus), distanceToTarget))

    adoptPursuitRoute(buildDirectWalkRoute(groundedStart, groundedTarget, enemy),
        enemy, targetPosition, 1)
    NAV.routeIsDirect = true
    return true
end

local function updatePursuitMovement(enemy, humanoid, root, enemyRoot)
    local benchedUntil = NAV.benched[enemy]
    if benchedUntil and os.clock() < benchedUntil then
        setMovementState("target unreachable, reselecting")
        return
    end

    local targetPosition = getStandOffPosition(root, enemyRoot)
    local now = os.clock()

    local targetChanged = NAV.enemy ~= enemy
    local targetMoved = not NAV.lastTarget or (targetPosition - NAV.lastTarget).Magnitude >= CFG.pathTargetMoveThreshold
    local inHazard = not isPositionSafeFromDamageBricks(root.Position, 0.5)
    local retryDelay = #NAV.waypoints == 0 and CFG.pathFailureRetryInterval or CFG.pathRecomputeInterval
    local canRecompute = (now - NAV.lastComputeTime >= retryDelay) or inHazard

    if not NAV.progressPosition then
        NAV.progressPosition = root.Position
        NAV.progressTime = now
    elseif (root.Position - NAV.progressPosition).Magnitude >= CFG.stuckProgressDistance then
        NAV.progressPosition = root.Position
        NAV.progressTime = now
    elseif NAV.index <= #NAV.waypoints
        and (root.Position - targetPosition).Magnitude > CFG.waypointAdvanceDistance
        and now - NAV.progressTime >= CFG.stuckTimeout then
        heavyDebug("Stuck", "Stuck timeout reached. Forcing path recompute.")
        -- A stall is usually a lip, a step or an invisible wall the route did not
        -- know about. Hopping costs nothing and clears most of them, on navmesh
        -- routes too - the mesh is baked without the game's invisible walls.
        humanoid.Jump = true
        NAV.needsRecompute = true
        NAV.progressPosition = root.Position
        NAV.progressTime = now
    end

    local wantsRecompute = targetChanged or ((targetMoved or NAV.needsRecompute or #NAV.waypoints == 0) and canRecompute)

    -- Throttle is tested before the string is built; formatting this every frame
    -- only to discard it was pure garbage generation.
    if RT.debugLevel >= DEBUG_NORMAL and (now - (debugThrottleClocks["move_state"] or -math.huge)) >= 1.0 then
        heavyDebugThrottled("move_state", 1.0, "Movement", string.format(
            "target=%s dist=%.1f | waypoints=%d idx=%d | changed=%s moved=%s needs=%s canRecompute=%s computing=%s | sinceCompute=%.2fs",
            enemy.Name,
            (root.Position - enemyRoot.Position).Magnitude,
            #NAV.waypoints, NAV.index,
            tostring(targetChanged), tostring(targetMoved), tostring(NAV.needsRecompute),
            tostring(canRecompute), tostring(NAV.computing),
            now - NAV.lastComputeTime))
    end

    if wantsRecompute then
        if not NAV.computing then
            heavyDebug("Movement", "Triggering path recompute for " .. enemy.Name)
            task.spawn(function()
                computePursuitPath(root, enemy, targetPosition)
            end)
        else
            heavyDebugThrottled("move_blocked", 2.0, "Movement", "Recompute wanted but a compute is already in flight.")
        end
    end

    while NAV.index <= #NAV.waypoints do
        local waypoint = NAV.waypoints[NAV.index]
        local waypointDelta = root.Position - waypoint.Position
        local horizontalDistance = Vector3.new(waypointDelta.X, 0, waypointDelta.Z).Magnitude

        if horizontalDistance > CFG.waypointAdvanceDistance or math.abs(waypointDelta.Y) > 4.5 then
            break
        end
        NAV.index = NAV.index + 1
    end

    local waypoint = NAV.waypoints[NAV.index]
    if waypoint then
        -- Actively moving toward something: the recovery detector is armed.
        NAV.driving = true
        if not CFG.faceTarget then
            humanoid.AutoRotate = true
        end

        local moveTarget = waypoint.Position
        local steerAngle = nil

        if NAV.routeIsDirect then
            -- Steer each frame rather than caching: obstacles are only known by
            -- probing, so the heading has to be re-evaluated as the bot moves.
            moveTarget, steerAngle = steerTowards(root, waypoint.Position, enemy)
            -- Only re-send the goal when the carrot has actually shifted. The
            -- steer result is a fixed world point held for a beat, so hammering
            -- MoveTo with it every frame just restarts the humanoid's approach
            -- and micro-stutters; the carrot still moves forward as the character
            -- advances, so MoveTo refreshes often enough not to time out.
            if not NAV.lastIssuedMove
                or (NAV.lastIssuedMove - moveTarget).Magnitude > CFG.moveReissueThreshold then
                humanoid:MoveTo(moveTarget)
                NAV.lastIssuedMove = moveTarget
            end

            -- World-space stall check, separate from progress-toward-enemy.
            -- Standing still while walking means the heading is into geometry
            -- the probes did not see, so retire that direction rather than
            -- re-picking it the moment the commitment window lapses.
            if not NAV.stallAnchor
                or (root.Position - NAV.stallAnchor).Magnitude >= CFG.headingStallDistance then
                NAV.stallAnchor = root.Position
                NAV.stallTime = now
            elseif now - NAV.stallTime >= CFG.headingStallTime then
                blockHeading(moveTarget - root.Position, now)
                NAV.stallAnchor = root.Position
                NAV.stallTime = now
                NAV.steerAngle = nil
                -- Drop the cache too, or the next frame would serve the very
                -- heading that was just blacklisted.
                NAV.steerCache = nil
                humanoid.Jump = true
            end

            -- Progress is measured against the enemy, not the steering target,
            -- so circling an obstacle does not read as success.
            local distanceNow = (root.Position - enemyRoot.Position).Magnitude
            if not NAV.directProgressPosition
                or (NAV.directProgressPosition - enemyRoot.Position).Magnitude - distanceNow > 2.0 then
                NAV.directProgressPosition = root.Position
                NAV.directProgressTime = now
            elseif now - NAV.directProgressTime >= CFG.directWalkGiveUpTime then
                NAV.benched[enemy] = now + CFG.unreachableCooldown
                NAV.directProgressPosition = nil
                NAV.directProgressTime = now
                NAV.forceRescan = true
                heavyDebug("Pathfinding", string.format(
                    "Walking at %s gained no ground in %.0fs. Benched for %.0fs; taking the next target.",
                    enemy.Name, CFG.directWalkGiveUpTime, CFG.unreachableCooldown))
                return
            end

            setMovementState(string.format("DIRECT %.0f studs%s%s",
                (root.Position - enemyRoot.Position).Magnitude,
                steerAngle and steerAngle ~= 0 and string.format(" (steer %d)", steerAngle) or "",
                (#NAV.blockedHeadings > 0 or #NAV.blockedAreas > 0)
                    and string.format(" [%dh %da blocked]", #NAV.blockedHeadings, #NAV.blockedAreas)
                    or ""))
            return
        end

        -- The navmesh is baked without the game's invisible walls, so a valid
        -- navmesh path can still run the character straight into one. Probe the
        -- short step to the next waypoint; if a solid is actually in the way,
        -- steer around it and ask for a fresh path rather than grinding on it.
        local moveGoal = waypoint.Position
        local toWp = Vector3.new(waypoint.Position.X - root.Position.X, 0,
            waypoint.Position.Z - root.Position.Z)
        local wpDist = toWp.Magnitude
        if wpDist > 1.5 then
            local probe = math.min(wpDist, CFG.wallProbeDistance)
            if castSolid(root.Position + Vector3.new(0, 1.5, 0),
                toWp.Unit * probe, getRaycastExclusions(enemy)) then
                moveGoal = steerTowards(root, waypoint.Position, enemy)
                NAV.needsRecompute = true
            end
        end

        if not NAV.lastIssuedMove
            or (NAV.lastIssuedMove - moveGoal).Magnitude > CFG.moveReissueThreshold then
            if waypoint.Action == Enum.PathWaypointAction.Jump then
                humanoid.Jump = true
            end
            humanoid:MoveTo(moveGoal)
            NAV.lastIssuedMove = moveGoal
            heavyDebug("Movement", string.format("MoveTo waypoint %d/%d", NAV.index, #NAV.waypoints), DEBUG_VERBOSE)
        end
        setMovementState(string.format("PURSUE wp %d/%d", NAV.index, #NAV.waypoints))
    elseif (root.Position - targetPosition).Magnitude > CFG.waypointAdvanceDistance then
        NAV.driving = true
        NAV.needsRecompute = true
        NAV.lastIssuedMove = nil
        heavyDebugThrottled("move_nopath", 1.0, "Movement", string.format(
            "NO PATH but target is %.1f studs away. Flagged for recompute.",
            (root.Position - targetPosition).Magnitude))
        setMovementState("NO PATH - retrying")
    elseif (root.Position - targetPosition).Magnitude > CFG.inRangeDeadband then
        if not NAV.lastIssuedMove
            or (NAV.lastIssuedMove - targetPosition).Magnitude > CFG.moveReissueThreshold then
            humanoid:MoveTo(targetPosition)
            NAV.lastIssuedMove = targetPosition
        end
        setMovementState("IN RANGE")
    else
        -- Inside the deadband: hold position and let facing and the attack run.
        -- The standoff point orbits the enemy as we move, so chasing it exactly
        -- made the character shuffle in place the whole time it was attacking.
        if NAV.lastIssuedMove and (NAV.lastIssuedMove - root.Position).Magnitude > 0.5 then
            humanoid:MoveTo(root.Position)
            NAV.lastIssuedMove = root.Position
        end
        setMovementState("IN RANGE")
    end
end

-- =========================================================================
-- ROUTED POINT WALKING (2.2.0)
--
-- walkTowardPoint used to be a straight steer at the point: fine on open floor,
-- useless across a drop, up a ramp with a lip, or around anything the navmesh
-- knows how to route past - which is exactly the terrain the manual path exists
-- for. It now asks the navmesh for a route to the point (slim agent, jumping
-- allowed) and follows it the way the pursuit follower does, steering directly
-- only when the navmesh has no answer. It also measures progress toward the
-- point itself, so a caller can tell "arrived" from "walked into a wall for six
-- seconds" and skip the point instead of parking on it forever.
-- =========================================================================

local function clearPointRoute()
    NAV.pointRoute = nil
    NAV.pointProgressDistance = nil
    NAV.pointProgressTime = 0
    NAV.walkAnchor = nil
    NAV.lastIssuedMove = nil
end

-- Off the Heartbeat: ComputeAsync yields.
local function computePointRoute(fromPosition, point)
    if NAV.computingPoint then return end
    NAV.computingPoint = true

    local ok, err = xpcall(function()
        local route = {
            target = point, waypoints = {}, index = 1, direct = true,
            computedAt = os.clock(), stalls = 0, needsRecompute = false,
        }
        if os.clock() >= NAV.navmeshDeadUntil then
            local path = PathfindingService:CreatePath({
                AgentRadius = CFG.pointRouteAgentRadius,
                AgentHeight = 4.5,
                AgentCanJump = true,
                AgentCanClimb = false,
                WaypointSpacing = 4,
            })
            local computed = pcall(function()
                path:ComputeAsync(fromPosition, point)
            end)
            if computed and path.Status == Enum.PathStatus.Success then
                local waypoints = path:GetWaypoints()
                if #waypoints > 1 then
                    route.waypoints = waypoints
                    route.index = 2
                    route.direct = false
                end
            end
            if route.direct then
                heavyDebugThrottled("point_nopath", 2.0, "PointWalk", string.format(
                    "No navmesh route to (%.0f, %.0f, %.0f) [%s]; steering directly.",
                    point.X, point.Y, point.Z, tostring(path.Status)))
            end
        end
        route.computedAt = os.clock()
        NAV.pointRoute = route
    end, debug.traceback)

    NAV.computingPoint = false
    if not ok then
        heavyDebugThrottled("point_err", 1.0, "FATAL", "Point route threw:\n" .. tostring(err))
    end
end

-- Walks toward `point`. Returns the planar distance remaining and a `stuck`
-- flag: true once the distance has not improved for CFG.pointGiveUpTime.
local function walkTowardPoint(humanoid, root, point)
    -- Facing goes back to the Humanoid so it looks where it is walking.
    releaseFacing(humanoid)
    NAV.driving = true

    local now = os.clock()
    local rootPos = root.Position
    local distance = Vector3.new(point.X - rootPos.X, 0, point.Z - rootPos.Z).Magnitude

    local route = NAV.pointRoute
    local sameTarget = route ~= nil
        and (route.target - point).Magnitude <= CFG.pointRouteTargetMoveThreshold

    -- Progress toward the point itself, not toward the current carrot, so
    -- circling an obstacle does not read as success.
    if not sameTarget or not NAV.pointProgressDistance then
        NAV.pointProgressDistance = distance
        NAV.pointProgressTime = now
    elseif distance < NAV.pointProgressDistance - 1.5 then
        NAV.pointProgressDistance = distance
        NAV.pointProgressTime = now
    end
    local stuck = sameTarget and (now - NAV.pointProgressTime) >= CFG.pointGiveUpTime

    -- (Re)route when the target changed, the route asked for one, or a navmesh
    -- route has gone stale. The old route keeps being followed while the new
    -- one computes, unless it was for a different point.
    if distance > 6 and not NAV.computingPoint
        and (not sameTarget or route.needsRecompute
            or (not route.direct and now - route.computedAt >= CFG.pointRouteRecomputeInterval)) then
        if not sameTarget then
            NAV.pointRoute = nil
            route = nil
        else
            route.needsRecompute = false
        end
        local from = rootPos
        task.spawn(function()
            computePointRoute(from, point)
        end)
    end

    local moveGoal = nil
    local usingRoute = false
    if route and sameTarget and not route.direct then
        local waypoints = route.waypoints
        while route.index <= #waypoints do
            local delta = rootPos - waypoints[route.index].Position
            if Vector3.new(delta.X, 0, delta.Z).Magnitude > CFG.waypointAdvanceDistance
                or math.abs(delta.Y) > 4.5 then
                break
            end
            route.index = route.index + 1
        end
        local waypoint = waypoints[route.index]
        if waypoint then
            usingRoute = true
            moveGoal = waypoint.Position
            if waypoint.Action == Enum.PathWaypointAction.Jump then
                humanoid.Jump = true
            end
            -- The navmesh is baked without the game's invisible walls: probe the
            -- short step to the waypoint and steer around a solid in the way.
            local toWp = Vector3.new(moveGoal.X - rootPos.X, 0, moveGoal.Z - rootPos.Z)
            local wpDist = toWp.Magnitude
            if wpDist > 1.5 then
                local probe = math.min(wpDist, CFG.wallProbeDistance)
                if castSolid(rootPos + Vector3.new(0, 1.5, 0), toWp.Unit * probe, getRaycastExclusions(nil)) then
                    moveGoal = steerTowards(root, moveGoal, nil)
                    route.needsRecompute = true
                end
            end
        end
    end
    if not moveGoal then
        moveGoal = steerTowards(root, point, nil)
    end

    if not NAV.lastIssuedMove
        or (NAV.lastIssuedMove - moveGoal).Magnitude > CFG.moveReissueThreshold then
        humanoid:MoveTo(moveGoal)
        NAV.lastIssuedMove = moveGoal
    end

    -- Stall: standing still while walking. Hop it and drop the steer
    -- commitment. A navmesh hop that stalls repeatedly is abandoned for direct
    -- steering (the mesh did not know about whatever we are stuck on); a direct
    -- heading that stalls is blacklisted like it is in pursuit.
    if not NAV.walkAnchor
        or (rootPos - NAV.walkAnchor).Magnitude >= CFG.headingStallDistance then
        NAV.walkAnchor = rootPos
        NAV.walkAnchorTime = now
    elseif now - NAV.walkAnchorTime >= CFG.headingStallTime then
        humanoid.Jump = true
        NAV.steerAngle = nil
        NAV.steerCache = nil
        NAV.walkAnchor = rootPos
        NAV.walkAnchorTime = now
        if usingRoute then
            route.stalls = route.stalls + 1
            if route.stalls >= CFG.pointRouteStallLimit then
                route.direct = true
                heavyDebug("PointWalk", string.format(
                    "Navmesh hop stalled %d times; steering directly for this point.", route.stalls))
            end
        else
            blockHeading(moveGoal - rootPos, now)
        end
    end

    return distance, stuck
end

-- Walk the hardcoded path. progressPath (run every frame) advances pathIndex as
-- waypoints are passed, so this just walks toward the current one. When the
-- path is used up it holds. Returns false if no path is set OR it is already
-- finished, so the caller can fall back to plain idle. A waypoint that cannot
-- be closed on for CFG.pointGiveUpTime is skipped rather than parked on.
local function followPath(humanoid, root)
    local count = #NAV.waypath
    if count == 0 or NAV.pathIndex > count then return false end

    local target = NAV.waypath[NAV.pathIndex]
    local distance, stuck = walkTowardPoint(humanoid, root, target)
    if stuck then
        heavyDebug("Path", string.format(
            "Waypoint #%d not getting closer for %.0fs; skipping to the next.",
            NAV.pathIndex, CFG.pointGiveUpTime))
        NAV.pathIndex = NAV.pathIndex + 1
        if NAV.pathIndex > count and CFG.loopPath then NAV.pathIndex = 1 end
        clearPointRoute()
        if S.refreshPathMarkers then S.refreshPathMarkers() end
    end
    setMovementState(string.format("PATH wp %d/%d (%.0f studs%s)",
        NAV.pathIndex, count, distance,
        (NAV.pointRoute and not NAV.pointRoute.direct) and ", routed" or ", direct"))
    return true
end

S.blockArea = blockArea
S.clearEscapeNodes = clearEscapeNodes
S.clearEscapeRoute = clearEscapeRoute
S.clearRenderedPath = clearRenderedPath
S.destroyFacingRig = destroyFacingRig
S.faceTowards = faceTowards
S.followEscapeRoute = followEscapeRoute
S.followPath = followPath
S.pruneBlockedAreas = pruneBlockedAreas
S.releaseFacing = releaseFacing
S.renderCurrentPath = renderCurrentPath
S.renderEscapeRoute = renderEscapeRoute
S.resetPursuitPath = resetPursuitPath
S.resolveEscapeRoute = resolveEscapeRoute
S.updatePursuitMovement = updatePursuitMovement
S.walkTowardPoint = walkTowardPoint
S.clearPointRoute = clearPointRoute
S.castSolid = castSolid
S.getRaycastExclusions = getRaycastExclusions
S.steerTowards = steerTowards
S.projectToGround = projectToGround
S.isPathSegmentClear = isPathSegmentClear
end
    end)()
    module(S)
end

-- ===================================== src/clone.lua =====================================
do
    local module = (function()
-- clone.lua - Clone evasion: a visible ring of candidate positions, and the dodge that uses it.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local CFG = S.CFG
local CL = S.CL
local NAV = S.NAV
local HZ = S.HZ
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local setMovementState = S.setMovementState
local getVisualRoot = S.getVisualRoot
local getPlayerHitboxMetrics = S.getPlayerHitboxMetrics
local isPositionSafeFromDamageBricks = S.isPositionSafeFromDamageBricks
local evaluateHazardPenaltyAtPoint = S.evaluateHazardPenaltyAtPoint
local projectToGround = S.projectToGround
local isPathSegmentClear = S.isPathSegmentClear
local releaseFacing = S.releaseFacing

-- =========================================================================
-- CLONE EVASION (2.9.0)
--
-- A ring of player-sized volumes around the character. Each one is a standing
-- offer: "if you were here instead, would anything be hitting you?" They are
-- re-tested continuously and their pads show the answer - green safe, red not.
-- When something is about to hit the character, the bot steps into the best
-- green one.
--
-- This is the same question the Legacy escape search asks, with two
-- differences. The candidates are FIXED relative to the character rather than
-- generated per escape, so the answer is stable frame to frame instead of
-- being re-derived under pressure. And they are on screen, so a dodge that
-- goes wrong can be watched rather than reasoned about from a log.
--
-- Projectiles are handled for free: safety goes through
-- isPositionSafeFromDamageBricks, which measures against hazardClosestPoint,
-- which already sweeps a moving hazard along the strip it will cross in the
-- next CFG.projectileLookahead seconds. A clone standing in the path of an
-- incoming projectile is therefore red before the projectile arrives, which is
-- the entire point of testing positions rather than testing contact.
-- =========================================================================

-- Where the ring sits, as flat offsets from the character. Rebuilt only when
-- the count, ring or radius settings change.
local function buildOffsets()
    local offsets = {}
    local rings = math.max(1, math.floor(CFG.cloneRings))
    local total = math.max(4, math.floor(CFG.cloneCount))
    local perRing = math.max(3, math.floor(total / rings))

    for ring = 1, rings do
        -- Inner rings sit proportionally closer; a single ring sits at the
        -- full radius.
        local scale = rings == 1 and 1 or (0.55 + 0.45 * ((ring - 1) / (rings - 1)))
        local radius = CFG.cloneRadius * scale
        -- Offset alternate rings by half a step so they interleave rather than
        -- lining up into spokes with gaps between them.
        local phase = (ring % 2 == 0) and (math.pi / perRing) or 0
        for i = 1, perRing do
            local angle = phase + (i - 1) * (2 * math.pi / perRing)
            table.insert(offsets, Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius))
        end
    end
    return offsets
end

local function destroyClones()
    if CL.folder then CL.folder:Destroy() end
    CL.folder = nil
    table.clear(CL.nodes)
    CL.chosen = nil
    CL.safeCount = 0
end

-- Builds the pool. Every clone is two parts: a tall prism the size of the
-- character, and a flat pad under it that carries the safe/danger colour.
local function buildClones()
    destroyClones()

    local folder = Instance.new("Folder")
    folder.Name = "CloneRing"
    folder.Parent = getVisualRoot()
    CL.folder = folder

    local _, radius, totalHeight = getPlayerHitboxMetrics()
    local width = math.max(radius * 2, 2)
    local offsets = buildOffsets()

    for i, offset in ipairs(offsets) do
        local prism = Instance.new("Part")
        prism.Name = "Clone_" .. i
        prism.Size = Vector3.new(width, totalHeight, width)
        prism.Anchored = true
        prism.CanCollide = false
        prism.CanQuery = false      -- invisible to our own raycasts
        prism.CanTouch = false
        prism.CastShadow = false
        prism.Material = Enum.Material.ForceField
        prism.Color = CFG.colorCloneSafe
        prism.Transparency = 0.82
        prism.Parent = folder

        local pad = Instance.new("Part")
        pad.Name = "Pad_" .. i
        pad.Size = Vector3.new(width, 0.25, width)
        pad.Anchored = true
        pad.CanCollide = false
        pad.CanQuery = false
        pad.CanTouch = false
        pad.CastShadow = false
        pad.Material = Enum.Material.Neon
        pad.Color = CFG.colorCloneSafe
        pad.Transparency = 0.25
        pad.Parent = folder

        table.insert(CL.nodes, {
            prism = prism, pad = pad, offset = offset,
            position = Vector3.zero, safe = false, penalty = math.huge, reachable = true,
        })
    end

    CL.signature = string.format("%d/%d/%.1f", CFG.cloneCount, CFG.cloneRings, CFG.cloneRadius)
    heavyDebug("Clone", string.format("Ring built: %d volumes across %d ring(s) at %.0f studs.",
        #CL.nodes, CFG.cloneRings, CFG.cloneRadius))
end

local function setCloneActive(active)
    CL.active = active
    if active then
        buildClones()
    else
        destroyClones()
        heavyDebug("Clone", "Clone evasion off; ring removed.")
    end
end

-- Per frame. Cheap: it only writes CFrames, and only when the mode is on.
-- Safety is a separate, throttled pass because it costs raycasts.
local function positionClones(root)
    local visible = CFG.showClones
    local _, _, totalHeight = getPlayerHitboxMetrics()
    local rootPos = root.Position
    -- Prisms take the character's yaw so they read as copies of it; the ring
    -- offsets stay in world space, so a safe spot does not move when you turn.
    local _, yaw = root.CFrame:ToOrientation()
    local rotation = CFrame.Angles(0, yaw, 0)
    local half = totalHeight * 0.5

    for _, node in ipairs(CL.nodes) do
        local target = rootPos + node.offset
        node.position = target
        local prism, pad = node.prism, node.pad
        if prism.Parent then
            prism.CFrame = CFrame.new(target) * rotation
            pad.CFrame = CFrame.new(target - Vector3.new(0, half, 0)) * rotation
            if prism.Transparency ~= (visible and 0.82 or 1) then
                prism.Transparency = visible and 0.82 or 1
                pad.Transparency = visible and 0.25 or 1
            end
        end
    end
end

-- Throttled. Marks each clone safe or not and recolours its pad.
local function evaluateClones(root)
    local now = os.clock()
    if now - CL.lastEvalTime < CFG.cloneEvalInterval then return end
    CL.lastEvalTime = now

    local rootPos = root.Position
    local safeColor, dangerColor = CFG.colorCloneSafe, CFG.colorCloneDanger
    local safeCount = 0

    for _, node in ipairs(CL.nodes) do
        -- Drop the candidate onto the floor: a clone hanging in the air over a
        -- pit is not somewhere the character can stand.
        local grounded = projectToGround(node.position, nil)
        local rise = grounded.Y - rootPos.Y
        local standable = rise < CFG.cloneMaxClimb and rise > -CFG.cloneMaxDrop
        node.position = Vector3.new(node.position.X, grounded.Y, node.position.Z)

        -- Safety, including anything moving: isPositionSafeFromDamageBricks
        -- measures against the swept path of a projectile, not its current
        -- position, so a clone in the line of fire is already unsafe.
        local clear = standable
            and isPositionSafeFromDamageBricks(node.position, CFG.cloneSafetyMargin)
        node.safe = clear and true or false
        node.penalty = clear and evaluateHazardPenaltyAtPoint(node.position) or math.huge
        node.reachable = standable

        local color = node.safe and safeColor or dangerColor
        if node.pad.Parent and node.pad.Color ~= color then
            node.pad.Color = color
            node.prism.Color = color
        end
        if node.safe then safeCount = safeCount + 1 end
    end

    CL.safeCount = safeCount
end

-- Picks the clone to run to. Lowest hazard penalty wins; distance breaks ties,
-- because a shorter dash is a dash you finish. The reachability raycast is
-- only paid for the handful of best candidates, not all of them.
local function chooseClone(root)
    local rootPos = root.Position
    local ranked = {}
    for _, node in ipairs(CL.nodes) do
        if node.safe then table.insert(ranked, node) end
    end
    if #ranked == 0 then return nil end

    table.sort(ranked, function(a, b)
        if math.abs(a.penalty - b.penalty) > 1.0 then return a.penalty < b.penalty end
        return (a.position - rootPos).Magnitude < (b.position - rootPos).Magnitude
    end)

    for i = 1, math.min(#ranked, 5) do
        if isPathSegmentClear(rootPos, ranked[i].position, nil) then
            return ranked[i]
        end
    end
    -- Nothing verified walkable: take the best-ranked anyway rather than stand
    -- in the damage, exactly as the Legacy escape does when validation fails.
    return ranked[1]
end

-- The dodge. Called from the hazard branch of the main loop while clone mode
-- is on. Returns true if it is driving the character.
local function runCloneEvasion(humanoid, root)
    if not CL.active or #CL.nodes == 0 then return false end
    local now = os.clock()

    -- Hold a chosen clone briefly: re-picking every frame under a moving
    -- hazard makes the character stutter between two equally good options.
    local chosen = CL.chosen
    local stale = not chosen
        or (now - CL.chosenAt) >= CFG.cloneCommitTime
        or not chosen.safe
    if stale then
        chosen = chooseClone(root)
        CL.chosen = chosen
        CL.chosenAt = now
    end

    if not chosen then
        heavyDebugThrottled("clone_none", 1.0, "Clone",
            "Every clone is red - nowhere in the ring is safe. Widen it (Clone radius) or the attack is bigger than the ring.")
        setMovementState("CLONE - no safe node")
        return false
    end

    releaseFacing(humanoid)
    humanoid:MoveTo(chosen.position)
    NAV.lastIssuedMove = chosen.position
    NAV.driving = true

    -- Arrived: let the next frame pick again rather than sitting on a node
    -- that may have gone red behind us.
    if (root.Position - chosen.position).Magnitude <= 2.5 then
        CL.chosen = nil
    end

    setMovementState(string.format("CLONE dodge (%d/%d safe)", CL.safeCount, #CL.nodes))
    return true
end

-- One entry point for the main loop: keep the ring in step with the character
-- and with the settings, whether or not anything is currently threatening.
local function cloneStep(root)
    if not CL.active then return end
    -- A settings change (count, rings, radius) rebuilds the pool rather than
    -- trying to reshape it in place.
    local signature = string.format("%d/%d/%.1f", CFG.cloneCount, CFG.cloneRings, CFG.cloneRadius)
    if signature ~= CL.signature then buildClones() end
    positionClones(root)
    evaluateClones(root)
end

S.setCloneActive = setCloneActive
S.destroyClones = destroyClones
S.buildClones = buildClones
S.cloneStep = cloneStep
S.runCloneEvasion = runCloneEvasion
end
    end)()
    module(S)
end

-- ===================================== src/path.lua =====================================
do
    local module = (function()
-- path.lua - Manual waypoint path: markers, editing, free-fly editor, progression, recovery.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local NAV = S.NAV
local CFG = S.CFG
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local UserInputService = S.UserInputService
local setMovementState = S.setMovementState
local LocalPlayer = S.LocalPlayer
local RunService = S.RunService
local Workspace = S.Workspace
local getVisualRoot = S.getVisualRoot
local walkTowardPoint = S.walkTowardPoint
local clearPointRoute = S.clearPointRoute
local resetPursuitPath = S.resetPursuitPath

-- =========================================================================
-- PATH EDITOR: fly the camera, click the map to drop ordered waypoints, and
-- reorder them in a small panel. Waypoints are plain world coordinates saved to
-- the config; the bot walks them (followPath) whenever it has nothing to fight,
-- and walks the nearest stretch of them to get out when it is wedged (recovery).
-- =========================================================================

-- In-world markers, one record per waypoint index: { orb, link, sphere }.
-- Built once per edit; passing a waypoint destroys just that record (2.1.0).
-- The old renderer destroyed and rebuilt every marker on the path each time a
-- single waypoint was passed - with Show Radius on that was a hundred-plus
-- Instances per crossing.

local function ensurePathFolder()
    if NAV.pathFolder and NAV.pathFolder.Parent then return NAV.pathFolder end
    local folder = Instance.new("Folder")
    folder.Name = "PathWaypoints"
    folder.Parent = getVisualRoot()
    NAV.pathFolder = folder
    table.clear(NAV.pathMarkers)
    return folder
end

local function destroyMarker(i)
    local marker = NAV.pathMarkers[i]
    if not marker then return end
    if marker.orb then marker.orb:Destroy() end
    if marker.link then marker.link:Destroy() end
    if marker.sphere then marker.sphere:Destroy() end
    NAV.pathMarkers[i] = nil
end

local function buildMarker(folder, i, withLink)
    local pos = NAV.waypath[i]
    local marker = {}

    if NAV.showRadius then
        local sphere = Instance.new("Part")
        sphere.Name = "Radius_" .. i
        sphere.Shape = Enum.PartType.Ball
        sphere.Size = Vector3.new(CFG.waypointClearRadius * 2, CFG.waypointClearRadius * 2,
            CFG.waypointClearRadius * 2)
        sphere.Position = pos
        sphere.Anchored = true
        sphere.CanCollide = false
        sphere.CanQuery = false
        sphere.CanTouch = false
        sphere.CastShadow = false
        sphere.Material = Enum.Material.ForceField
        sphere.Color = Color3.fromRGB(90, 190, 255)
        sphere.Transparency = 0.7
        sphere.Parent = folder
        marker.sphere = sphere
    end

    local orb = Instance.new("Part")
    orb.Name = "Waypoint_" .. i
    orb.Shape = Enum.PartType.Ball
    orb.Size = Vector3.new(1.6, 1.6, 1.6)
    orb.Position = pos
    orb.Anchored = true
    orb.CanCollide = false
    orb.CanQuery = false          -- invisible to our own raycasts
    orb.CanTouch = false
    orb.CastShadow = false
    orb.Material = Enum.Material.Neon
    orb.Color = CFG.colorWaypoint
    orb.Transparency = 0.25
    orb.Parent = folder
    marker.orb = orb

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "Label"
    billboard.Size = UDim2.fromOffset(46, 26)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, 2.4, 0)
    billboard.AlwaysOnTop = true
    billboard.Adornee = orb
    billboard.Parent = orb

    local label = Instance.new("TextLabel")
    label.Size = UDim2.fromScale(1, 1)
    label.BackgroundTransparency = 1
    label.Font = Enum.Font.GothamBold
    label.Text = "#" .. i
    label.TextColor3 = CFG.colorWaypoint
    label.TextStrokeTransparency = 0.2
    label.TextScaled = true
    label.Parent = billboard

    -- A faint line to the previous waypoint (only if it is also still live).
    if withLink and NAV.waypath[i - 1] then
        local prev = NAV.waypath[i - 1]
        local mid = prev:Lerp(pos, 0.5)
        local link = Instance.new("Part")
        link.Name = "Link_" .. i
        link.Anchored = true
        link.CanCollide = false
        link.CanQuery = false
        link.CanTouch = false
        link.CastShadow = false
        link.Material = Enum.Material.Neon
        link.Color = CFG.colorWaypoint
        link.Transparency = 0.6
        link.Size = Vector3.new(0.15, 0.15, (pos - prev).Magnitude)
        link.CFrame = CFrame.lookAt(mid, pos)
        link.Parent = folder
        marker.link = link
    end

    NAV.pathMarkers[i] = marker
end

-- Full rebuild: every live waypoint (index >= pathIndex) gets a marker. Used
-- when the list itself changes, on load, on a loop wrap, and when the radius
-- overlay is toggled or resized - never per frame and never on progression.
local function renderPathMarkers()
    if NAV.pathFolder then NAV.pathFolder:Destroy() end
    NAV.pathFolder = nil
    table.clear(NAV.pathMarkers)
    if #NAV.waypath == 0 then return end

    local folder = ensurePathFolder()
    for i = 1, #NAV.waypath do
        if i >= NAV.pathIndex then
            buildMarker(folder, i, i > NAV.pathIndex)
        end
    end
end

-- Incremental: drop the markers of waypoints now behind pathIndex, and the link
-- leading into the first live one. Touches only what changed.
local function refreshPathMarkers()
    local first = NAV.pathIndex
    local stale = nil
    for i in pairs(NAV.pathMarkers) do
        if i < first then
            stale = stale or {}
            stale[#stale + 1] = i
        end
    end
    if stale then
        for _, i in ipairs(stale) do destroyMarker(i) end
    end
    local marker = NAV.pathMarkers[first]
    if marker and marker.link then
        marker.link:Destroy()
        marker.link = nil
    end
end

-- refreshPathPanel is late-bound: the UI module assigns S.refreshPathPanel.

local function addWaypoint(pos)
    table.insert(NAV.waypath, pos)
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
    heavyDebug("Path", string.format("Added waypoint #%d at (%.0f, %.0f, %.0f).",
        #NAV.waypath, pos.X, pos.Y, pos.Z))
end

local function removeWaypoint(index)
    if not NAV.waypath[index] then return end
    table.remove(NAV.waypath, index)
    if NAV.pathIndex > #NAV.waypath then NAV.pathIndex = 1 end
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

local function moveWaypoint(index, delta)
    local target = index + delta
    if not NAV.waypath[index] or not NAV.waypath[target] then return end
    NAV.waypath[index], NAV.waypath[target] = NAV.waypath[target], NAV.waypath[index]
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

local function clearWaypath()
    table.clear(NAV.waypath)
    NAV.pathIndex = 1
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

-- Called every frame: as the player passes within the clear radius of the NEXT
-- waypoint in order, that waypoint is marked passed and its marker clears. Only
-- the next one in sequence is ever consumed (chronological), and NAV.waypath -
-- the saved list - is never touched, so the config stays permanent.
local function progressPath(rootPos)
    -- Recovery drives pathIndex itself while it is walking the path.
    if NAV.recovery then return end
    local count = #NAV.waypath
    if count == 0 or NAV.pathIndex > count then return end
    if NAV.pathIndex < 1 then NAV.pathIndex = 1 end

    local passed = false
    while NAV.pathIndex <= count
        and (rootPos - NAV.waypath[NAV.pathIndex]).Magnitude <= CFG.waypointClearRadius do
        NAV.pathIndex = NAV.pathIndex + 1
        passed = true
    end

    if passed then
        clearPointRoute()
        if NAV.pathIndex > count and CFG.loopPath then
            NAV.pathIndex = 1
            renderPathMarkers()
        else
            refreshPathMarkers()
        end
    end
end

-- =========================================================================
-- RECOVERY (2.2.0): the manual path as the last resort.
--
-- Normal navigation - navmesh, the retry ladder, direct steering, the heading
-- and area blacklists - is what gets the bot to enemies. When all of it has
-- still left the character loitering in one spot, the one thing that is known
-- to be walkable is the path the user laid down by hand. Recovery walks to the
-- nearest waypoint (routed, see walkTowardPoint) and on along the path for a
-- couple of points, then hands back to pursuit with a clean slate. Re-sticking
-- soon after continues further along the path instead of returning to the
-- same nearest point, and each repeat walks a longer stretch.
-- =========================================================================

local function nearestWaypointIndex(position)
    local best, bestScore = nil, math.huge
    for i, p in ipairs(NAV.waypath) do
        local score = Vector3.new(p.X - position.X, 0, p.Z - position.Z).Magnitude
        -- A waypoint well above us (a ledge overhead) is not a way out from here.
        if p.Y - position.Y > CFG.maxClimbHeight then score = score + 40 end
        if score < bestScore then best, bestScore = i, score end
    end
    return best
end

local function exitRecovery(reason)
    local recovery = NAV.recovery
    if not recovery then return end
    NAV.recovery = nil
    NAV.lastRecoveryEnd = os.clock()
    NAV.lastRecoveryIndex = recovery.index
    NAV.stuckAnchor = nil
    clearPointRoute()
    resetPursuitPath()
    -- The wedge is behind us: let pursuit retry everything it had given up on.
    table.clear(NAV.benched)
    NAV.forceRescan = true
    heavyDebug("Recovery", string.format(
        "Recovery over (%s) after %.1fs; back to normal navigation at path #%d.",
        reason, os.clock() - recovery.startedAt, recovery.index))
end

local function enterRecovery(root, reason)
    if not CFG.recoveryEnabled or NAV.recovery then return false end
    if #NAV.waypath == 0 then
        heavyDebugThrottled("recovery_nopath", 10.0, "Recovery",
            "Stuck (" .. reason .. ") but no manual path is set, so there is nothing to recover along. Lay one down in Edit Path.")
        return false
    end

    local now = os.clock()
    local remaining = CFG.recoveryWaypoints
    local index
    if NAV.lastRecoveryIndex and NAV.waypath[NAV.lastRecoveryIndex]
        and now - NAV.lastRecoveryEnd <= CFG.recoveryRepeatWindow then
        -- Stuck again right after a recovery: the nearest waypoint is probably
        -- the one we just walked back from. Continue along the path instead,
        -- and further this time.
        index = NAV.lastRecoveryIndex
        remaining = remaining + CFG.recoveryEscalation
    else
        index = nearestWaypointIndex(root.Position)
    end
    -- Walking to a waypoint we are already standing on achieves nothing.
    if (NAV.waypath[index] - root.Position).Magnitude <= CFG.recoveryArriveRadius then
        index = index + 1
        if index > #NAV.waypath then
            index = CFG.loopPath and 1 or #NAV.waypath
        end
    end

    NAV.recovery = {
        index = index,
        remaining = remaining,
        deadline = now + CFG.recoveryMaxTime,
        startedAt = now,
        stuckAt = root.Position,
    }
    NAV.pathIndex = index
    renderPathMarkers()
    clearPointRoute()
    resetPursuitPath()
    NAV.stuckAnchor = nil
    heavyDebug("Recovery", string.format(
        "STUCK (%s) at (%.0f, %.0f, %.0f). Walking the manual path from #%d for %d waypoint(s).",
        reason, root.Position.X, root.Position.Y, root.Position.Z, index, remaining))
    setMovementState(string.format("RECOVERY: to path #%d", index))
    return true
end

-- The recovery branch of the main loop. Returns false once recovery has ended.
local function runRecovery(humanoid, root)
    local recovery = NAV.recovery
    if not recovery then return false end
    local now = os.clock()

    local target = NAV.waypath[recovery.index]
    if not target then
        exitRecovery("ran out of path")
        return false
    end
    if now > recovery.deadline then
        exitRecovery("time limit")
        return false
    end

    -- A mob in our face is not a wedge; fight it.
    local enemy = NAV.cachedEnemy
    if enemy then
        local enemyRoot = enemy:FindFirstChild("HumanoidRootPart") or enemy.PrimaryPart
        if enemyRoot and (enemyRoot.Position - root.Position).Magnitude <= CFG.attackRange then
            exitRecovery("enemy in reach")
            return false
        end
    end

    local distance, stuck = walkTowardPoint(humanoid, root, target)
    if distance <= CFG.recoveryArriveRadius or stuck then
        if stuck then
            heavyDebug("Recovery", string.format(
                "Path #%d not getting closer for %.0fs; skipping it.", recovery.index, CFG.pointGiveUpTime))
        end
        recovery.index = recovery.index + 1
        if recovery.index > #NAV.waypath then
            if CFG.loopPath then
                recovery.index = 1
            else
                exitRecovery("end of path")
                return false
            end
        end
        recovery.remaining = recovery.remaining - 1
        NAV.pathIndex = recovery.index
        refreshPathMarkers()
        clearPointRoute()
        if recovery.remaining <= 0 then
            exitRecovery("walked the segment")
            return false
        end
    end

    setMovementState(string.format("RECOVERY wp #%d (%.0f studs, %d to go)",
        recovery.index, distance, recovery.remaining))
    return true
end

-- Stuck detector, called once per frame by the main loop AFTER the branch ran,
-- so `driving` reflects this frame. Loitering inside recoveryStuckRadius for
-- recoveryStuckTime while actively trying to move means the normal navigation
-- has wedged itself. Not armed while dodging (holding still inside a
-- telegraph's clearance is the escape logic working) or while standing in
-- range attacking (that is not moving on purpose).
local function updateStuckDetector(root, driving, inHazard, now)
    if NAV.recovery or not driving or inHazard then
        NAV.stuckAnchor = nil
        return false
    end
    if not NAV.stuckAnchor
        or (root.Position - NAV.stuckAnchor).Magnitude > CFG.recoveryStuckRadius then
        NAV.stuckAnchor = root.Position
        NAV.stuckAnchorTime = now
        return false
    end
    if now - NAV.stuckAnchorTime >= CFG.recoveryStuckTime then
        NAV.stuckAnchor = nil
        return enterRecovery(root, string.format(
            "within %.0f studs for %.1fs", CFG.recoveryStuckRadius, CFG.recoveryStuckTime))
    end
    return false
end

-- Free-fly camera + click-to-place. While armed: hold RIGHT mouse to look, WASD
-- to fly (E/Q up/down), and LEFT-click a spot on the map to drop a waypoint there.
local function setPathEditEnabled(enabled)
    for _, connection in ipairs(NAV.pathEditConnections) do
        connection:Disconnect()
    end
    table.clear(NAV.pathEditConnections)
    NAV.pathEditEnabled = enabled

    local camera = Workspace.CurrentCamera
    if not enabled then
        if camera and NAV.savedCameraType then
            camera.CameraType = NAV.savedCameraType
        elseif camera then
            camera.CameraType = Enum.CameraType.Custom
        end
        table.clear(NAV.freecamKeys)
        NAV.freecamLooking = false
        pcall(function() UserInputService.MouseBehavior = Enum.MouseBehavior.Default end)
        setMovementState("path editor off")
        return
    end

    if not camera then return end
    NAV.savedCameraType = camera.CameraType
    camera.CameraType = Enum.CameraType.Scriptable
    NAV.freecamCFrame = camera.CFrame
    local _, y, _ = camera.CFrame:ToOrientation()
    NAV.freecamYaw = y
    NAV.freecamPitch = 0
    table.clear(NAV.freecamKeys)
    NAV.freecamLooking = false

    local KEY_VECTORS = {
        [Enum.KeyCode.W] = Vector3.new(0, 0, -1),
        [Enum.KeyCode.S] = Vector3.new(0, 0, 1),
        [Enum.KeyCode.A] = Vector3.new(-1, 0, 0),
        [Enum.KeyCode.D] = Vector3.new(1, 0, 0),
        [Enum.KeyCode.E] = Vector3.new(0, 1, 0),
        [Enum.KeyCode.Q] = Vector3.new(0, -1, 0),
    }

    table.insert(NAV.pathEditConnections, UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if KEY_VECTORS[input.KeyCode] then
            NAV.freecamKeys[input.KeyCode] = true
        elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
            NAV.freecamLooking = true
            -- Pin the cursor so the look delta keeps coming instead of stopping
            -- dead the moment the pointer reaches a screen edge.
            pcall(function()
                UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
            end)
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            -- Drop a waypoint where the cursor is pointing on the map.
            local mouse = LocalPlayer:GetMouse()
            local hit = mouse.Hit
            if hit then addWaypoint(hit.Position) end
        end
    end))

    table.insert(NAV.pathEditConnections, UserInputService.InputEnded:Connect(function(input)
        if KEY_VECTORS[input.KeyCode] then
            NAV.freecamKeys[input.KeyCode] = nil
        elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
            NAV.freecamLooking = false
            pcall(function()
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            end)
        end
    end))

    table.insert(NAV.pathEditConnections, UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement and NAV.freecamLooking then
            local s = math.rad(CFG.freecamLookSensitivity)
            NAV.freecamYaw = NAV.freecamYaw - input.Delta.X * s
            NAV.freecamPitch = math.clamp(NAV.freecamPitch - input.Delta.Y * s,
                math.rad(-89), math.rad(89))
        end
    end))

    table.insert(NAV.pathEditConnections, RunService.RenderStepped:Connect(function(dt)
        local cam = Workspace.CurrentCamera
        if not cam or not NAV.pathEditEnabled then return end
        local rot = CFrame.Angles(0, NAV.freecamYaw, 0) * CFrame.Angles(NAV.freecamPitch, 0, 0)
        local move = Vector3.zero
        for key, vec in pairs(KEY_VECTORS) do
            if NAV.freecamKeys[key] then move = move + vec end
        end
        local pos = NAV.freecamCFrame.Position
        if move.Magnitude > 0 then
            pos = pos + (rot:VectorToWorldSpace(move.Unit) * CFG.freecamSpeed * dt)
        end
        NAV.freecamCFrame = CFrame.new(pos) * rot
        cam.CFrame = NAV.freecamCFrame
    end))

    setMovementState("path editor: fly (WASD/EQ), right-drag look, left-click to place")
    heavyDebug("Path", "Path editor armed. WASD+EQ fly, hold right mouse to look, left-click places a waypoint.")
end

S.clearWaypath = clearWaypath
S.moveWaypoint = moveWaypoint
S.progressPath = progressPath
S.removeWaypoint = removeWaypoint
S.renderPathMarkers = renderPathMarkers
S.refreshPathMarkers = refreshPathMarkers
S.setPathEditEnabled = setPathEditEnabled
S.enterRecovery = enterRecovery
S.exitRecovery = exitRecovery
S.runRecovery = runRecovery
S.updateStuckDetector = updateStuckDetector
end
    end)()
    module(S)
end

-- ===================================== src/macro.lua =====================================
do
    local module = (function()
-- macro.lua - Macro Waypoints: record a run, list and reorder the recordings, play them back.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local CFG = S.CFG
local MC = S.MC
local NAV = S.NAV
local LocalPlayer = S.LocalPlayer
local Workspace = S.Workspace
local UserInputService = S.UserInputService
local VirtualInputManager = S.VirtualInputManager
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local setMovementState = S.setMovementState
local getVisualRoot = S.getVisualRoot
local walkTowardPoint = S.walkTowardPoint
local clearPointRoute = S.clearPointRoute
local releaseFacing = S.releaseFacing
local faceTowards = S.faceTowards
local setPathEditEnabled = S.setPathEditEnabled

-- =========================================================================
-- MACRO WAYPOINTS (2.5.0)
--
-- A macro is a recording of a run: where the character went, and what it did
-- along the way. Recording samples the root position on a distance/time budget
-- and logs every action input (attack click, Q, E, jump) against the sample it
-- happened at. Playback walks to the macro's start with the normal routed
-- pathfinding, then follows the samples in order, firing each action as its
-- anchor sample is reached.
--
-- WHY POSITIONS AND NOT HELD KEYS. The obvious reading of "record the inputs
-- and play them back" is to store W-down at 0.4s, W-up at 2.1s and re-send
-- them. That desynchronises within seconds in practice: a different framerate,
-- a slightly different spawn point, one clip on a doorframe, a knockback, any
-- of it shifts the character off the recorded line and every later input then
-- lands somewhere else, with no way to notice or recover. A position is
-- absolute - the replay steers back onto the recorded route after any
-- disturbance, and a macro recorded at 30fps plays correctly at 144. The
-- ACTIONS are still exactly the recorded inputs; they are anchored to where
-- along the route they were made rather than to a wall-clock offset, so they
-- stay attached to the thing they were aimed at.
-- =========================================================================

local ACTION_KEYS = {
    [Enum.KeyCode.Q] = "q",
    [Enum.KeyCode.E] = "e",
    [Enum.KeyCode.Space] = "jump",
}

local function macroCount(macro)
    return macro and macro.samples and #macro.samples or 0
end

-- One recorded moment: where the torso was, and which way it and the camera
-- were pointing.
--
-- The facing is stored as a LOOK VECTOR rather than an angle. Roblox's look
-- direction for yaw t is (-sin t, 0, -cos t) - the minus signs matter, and
-- 2.7.0 got them wrong, which pointed the replay a clean 180 degrees away from
-- where you had been standing. A unit vector has no sign convention to get
-- wrong on the way back out.
--
-- Both are recorded because they are different things. A humanoid keeps its
-- torso upright, so torso pitch is ~0 whatever you do with the mouse; the pitch
-- you actually aimed with lives on the camera.
local function sampleAt(root, t)
    local look = root.CFrame.LookVector
    local sample = {
        t = t,
        -- One decimal is well under the arrive radius and keeps the saved JSON
        -- to a sane size; a long macro is thousands of samples.
        x = math.floor(root.Position.X * 10 + 0.5) / 10,
        y = math.floor(root.Position.Y * 10 + 0.5) / 10,
        z = math.floor(root.Position.Z * 10 + 0.5) / 10,
        lx = math.floor(look.X * 1000 + 0.5) / 1000,
        ly = math.floor(look.Y * 1000 + 0.5) / 1000,
        lz = math.floor(look.Z * 1000 + 0.5) / 1000,
    }
    local camera = Workspace.CurrentCamera
    if camera then
        local cameraLook = camera.CFrame.LookVector
        sample.cx = math.floor(cameraLook.X * 1000 + 0.5) / 1000
        sample.cy = math.floor(cameraLook.Y * 1000 + 0.5) / 1000
        sample.cz = math.floor(cameraLook.Z * 1000 + 0.5) / 1000
    end
    return sample
end

-- The torso facing of a sample, or nil. Handles the 2.7.0 format, which stored
-- a bare yaw angle in `r`.
local function sampleLook(sample)
    if not sample then return nil end
    if sample.lx then
        local look = Vector3.new(sample.lx, sample.ly, sample.lz)
        if look.Magnitude > 0.01 then return look end
        return nil
    end
    if sample.r then
        return Vector3.new(-math.sin(sample.r), 0, -math.cos(sample.r))
    end
    return nil
end

local function samplePosition(macro, index)
    local sample = macro.samples[index]
    if not sample then return nil end
    return Vector3.new(sample.x, sample.y, sample.z)
end

-- ---------------------------------------------------------------- route draw
local function clearMacroRoute()
    if MC.routeFolder then MC.routeFolder:Destroy() end
    MC.routeFolder = nil
end

-- Draws the selected macro's route: a sparse line of dots plus a start orb.
-- Capped, and rebuilt only on selection / recording changes, never per frame.
local function renderMacroRoute(index)
    clearMacroRoute()
    if not CFG.macroShowRoute then return end
    local macro = MC.macros[index or MC.playIndex]
    local count = macroCount(macro)
    if count == 0 then return end

    local folder = Instance.new("Folder")
    folder.Name = "MacroRoute"
    folder.Parent = getVisualRoot()
    MC.routeFolder = folder

    local budget = 90
    local step = math.max(1, math.ceil(count / budget))
    for i = 1, count, step do
        local position = samplePosition(macro, i)
        local dot = Instance.new("Part")
        dot.Name = "MacroNode"
        dot.Shape = Enum.PartType.Ball
        dot.Size = Vector3.new(0.5, 0.5, 0.5)
        dot.Position = position
        dot.Anchored = true
        dot.CanCollide = false
        dot.CanQuery = false
        dot.CanTouch = false
        dot.CastShadow = false
        dot.Material = Enum.Material.Neon
        dot.Color = CFG.colorMacro
        dot.Transparency = 0.4
        dot.Parent = folder
    end

    local start = Instance.new("Part")
    start.Name = "MacroStart"
    start.Shape = Enum.PartType.Ball
    start.Size = Vector3.new(2.2, 2.2, 2.2)
    start.Position = samplePosition(macro, 1)
    start.Anchored = true
    start.CanCollide = false
    start.CanQuery = false
    start.CanTouch = false
    start.CastShadow = false
    start.Material = Enum.Material.Neon
    start.Color = Color3.fromRGB(120, 255, 160)
    start.Transparency = 0.2
    start.Parent = folder

    local billboard = Instance.new("BillboardGui")
    billboard.Size = UDim2.fromOffset(150, 26)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
    billboard.AlwaysOnTop = true
    billboard.Adornee = start
    billboard.Parent = start
    local label = Instance.new("TextLabel")
    label.Size = UDim2.fromScale(1, 1)
    label.BackgroundTransparency = 1
    label.Font = Enum.Font.GothamBold
    label.Text = "START: " .. (macro.name or "macro")
    label.TextColor3 = Color3.fromRGB(150, 255, 190)
    label.TextStrokeTransparency = 0.2
    label.TextSize = 13
    label.Parent = billboard
end

-- ---------------------------------------------------------------- recording
-- ONLY the per-recording listener. The global bind listener lives in
-- MC.connections and must survive this: it used to share the table, so
-- starting a recording disconnected the record bind and it never fired again.
local function disconnectRecordInputs()
    for _, connection in ipairs(MC.recordConnections) do
        connection:Disconnect()
    end
    table.clear(MC.recordConnections)
end

local function stopRecording()
    if not MC.recording then return end
    MC.recording = false
    disconnectRecordInputs()

    local samples = MC.samples or {}
    MC.samples, MC.actions = nil, nil

    if #samples < 2 then
        heavyDebug("Macro", "Recording discarded: fewer than two position samples.")
        setMovementState("recording discarded (too short)")
        return
    end

    local macro = {
        name = string.format("Macro %d", #MC.macros + 1),
        samples = samples,
        actions = MC.lastActions or {},
        duration = samples[#samples].t,
        recordedAt = os.time(),
    }
    MC.lastActions = nil
    table.insert(MC.macros, macro)
    heavyDebug("Macro", string.format(
        "Recorded '%s': %d samples over %.1fs, %d action(s). Rename it in the panel, then Save.",
        macro.name, #macro.samples, macro.duration, #macro.actions))
    setMovementState(string.format("recorded %.0fs macro", macro.duration))
    renderMacroRoute(#MC.macros)
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function startRecording()
    if MC.recording then return end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then
        heavyDebug("Macro", "Cannot record: no character.")
        return
    end

    -- The bot must not be driving while you are. Recording is you playing.
    if RT.farmEnabled then
        RT.farmEnabled = false
        if S.setLoopButtonState then S.setLoopButtonState() end
        heavyDebug("Macro", "Loop switched off for recording - you are driving now.")
    end

    -- And the camera must be yours. The waypoint editor's free-fly camera
    -- detaches from the character entirely, so recording with it armed would
    -- capture a route the character never walked.
    if NAV.pathEditEnabled then
        setPathEditEnabled(false)
        if S.setFreecamButtonState then S.setFreecamButtonState() end
        heavyDebug("Macro", "Free-fly editor switched off: a macro is recorded from your own camera.")
    end

    MC.recording = true
    MC.recordStart = os.clock()
    MC.samples = { sampleAt(root, 0) }
    MC.actions = {}
    MC.lastActions = MC.actions
    MC.lastSampleTime = MC.recordStart
    MC.lastSamplePosition = root.Position

    disconnectRecordInputs()
    -- Actions are logged against the sample index they happened at, which is
    -- what keeps them attached to the place they were aimed at.
    table.insert(MC.recordConnections, UserInputService.InputBegan:Connect(function(input, processed)
        if processed or not MC.recording then return end
        local kind
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            kind = "click"
        else
            kind = ACTION_KEYS[input.KeyCode]
        end
        if not kind then return end
        table.insert(MC.actions, {
            t = os.clock() - MC.recordStart,
            i = #MC.samples,
            kind = kind,
        })
    end))

    heavyDebug("Macro", "RECORDING. Play the route normally; press the bind again to stop.")
    setMovementState("RECORDING macro")
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function toggleRecording()
    if MC.recording then stopRecording() else startRecording() end
end

-- Called every frame while recording, from the scanner loop (which runs whether
-- or not the bot is farming - and it is not, while you drive).
local function recordStep()
    if not MC.recording then return end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local now = os.clock()
    local position = root.Position
    local moved = MC.lastSamplePosition and (position - MC.lastSamplePosition).Magnitude or math.huge
    if moved < CFG.macroSampleDistance and (now - MC.lastSampleTime) < CFG.macroSampleInterval then
        return
    end

    MC.lastSampleTime = now
    MC.lastSamplePosition = position
    table.insert(MC.samples, sampleAt(root, now - MC.recordStart))

    if #MC.samples >= CFG.macroMaxSamples then
        heavyDebug("Macro", "Sample limit reached; stopping the recording here.")
        stopRecording()
    end
end

-- ---------------------------------------------------------------- the list
local function removeMacro(index)
    if not MC.macros[index] then return end
    local macro = table.remove(MC.macros, index)
    heavyDebug("Macro", string.format("Deleted '%s'.", macro.name))
    if MC.playIndex > #MC.macros then MC.playIndex = 1 end
    clearMacroRoute()
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function moveMacro(index, delta)
    local target = index + delta
    if not MC.macros[index] or not MC.macros[target] then return end
    MC.macros[index], MC.macros[target] = MC.macros[target], MC.macros[index]
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function renameMacro(index, name)
    local macro = MC.macros[index]
    if not macro then return end
    macro.name = name
end

local function clearMacros()
    table.clear(MC.macros)
    MC.playIndex = 1
    clearMacroRoute()
    heavyDebug("Macro", "All macros for this map deleted.")
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

-- ---------------------------------------------------------------- playback
local function fireAction(kind, humanoid)
    if kind == "jump" then
        if humanoid then humanoid.Jump = true end
        return
    end
    if kind == "click" then
        local position = UserInputService:GetMouseLocation()
        pcall(function()
            VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
        end)
        task.delay(CFG.clickHoldDuration, function()
            pcall(function()
                VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, false, game, 0)
            end)
        end)
        return
    end
    local keyCode = kind == "q" and Enum.KeyCode.Q or kind == "e" and Enum.KeyCode.E or nil
    if not keyCode then return end
    pcall(function() VirtualInputManager:SendKeyEvent(true, keyCode, false, game) end)
    task.delay(CFG.abilityHoldDuration, function()
        pcall(function() VirtualInputManager:SendKeyEvent(false, keyCode, false, game) end)
    end)
end

local function resetPlaybackCursors()
    MC.playPhase = "approach"
    MC.playCursor = 1
    MC.playActionCursor = 1
    MC.playProgressDistance = nil
    MC.playProgressTime = os.clock()
    MC.playSkips = 0
    clearPointRoute()
end

local function stopPlayback(reason)
    if not MC.playing then return end
    MC.playing = false
    resetPlaybackCursors()
    clearPointRoute()
    heavyDebug("Macro", "Playback stopped: " .. tostring(reason or "asked to"))
    setMovementState("macro playback stopped")
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function playMacro(index)
    local macro = MC.macros[index]
    if not macro or macroCount(macro) < 2 then
        heavyDebug("Macro", "Nothing to play.")
        return
    end
    if MC.recording then stopRecording() end
    MC.playIndex = index
    MC.playing = true
    resetPlaybackCursors()
    renderMacroRoute(index)

    -- Playback needs the main loop running, since that is what drives the
    -- character each frame.
    if not RT.farmEnabled then
        RT.farmEnabled = true
        if S.setLoopButtonState then S.setLoopButtonState() end
        heavyDebug("Macro", "Loop switched on for playback.")
    end

    heavyDebug("Macro", string.format(
        "Playing '%s' (%d samples, %.1fs, %d actions). Walking to its start first.",
        macro.name, macroCount(macro), macro.duration or 0, #(macro.actions or {})))
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

local function advanceToNextMacro()
    local next = MC.playIndex + 1
    if next > #MC.macros then
        if not CFG.macroLoop then
            stopPlayback("reached the end of the list")
            return
        end
        next = 1
    end
    MC.playIndex = next
    resetPlaybackCursors()
    renderMacroRoute(next)
    heavyDebug("Macro", string.format("Next macro: '%s'.", MC.macros[next].name))
end

-- The playback branch of the main loop. Returns false once playback has ended.
local function runMacroPlayback(humanoid, root)
    if not MC.playing then return false end
    local macro = MC.macros[MC.playIndex]
    if not macro or macroCount(macro) < 2 then
        stopPlayback("the macro went away")
        return false
    end

    local now = os.clock()
    local rootPos = root.Position

    -- Phase 1: get to where the recording started, using the normal routed
    -- pathfinding - the character may be anywhere, and only the recorded part
    -- of the route is known to be walkable.
    if MC.playPhase == "approach" then
        local start = samplePosition(macro, 1)
        local distance, stuck = walkTowardPoint(humanoid, root, start)
        if distance <= CFG.macroStartRadius then
            MC.playPhase = "replay"
            MC.playCursor = 1
            MC.playActionCursor = 1
            MC.playProgressDistance = nil
            MC.playProgressTime = now
            MC.playSkips = 0
            clearPointRoute()
            heavyDebug("Macro", string.format("At the start of '%s'; replaying.", macro.name))
        elseif stuck then
            heavyDebug("Macro", string.format(
                "Cannot reach the start of '%s'; skipping it.", macro.name))
            advanceToNextMacro()
        else
            setMovementState(string.format("MACRO '%s' - to start (%.0f studs)", macro.name, distance))
        end
        return true
    end

    -- Phase 2: follow the recorded samples. Several may be consumed in one
    -- frame: the recording samples every 2.5 studs and the arrive radius is
    -- wider than that, which is what stops the replay crawling.
    local samples = macro.samples
    local count = #samples
    while MC.playCursor <= count do
        local point = samplePosition(macro, MC.playCursor)
        local delta = rootPos - point
        if Vector3.new(delta.X, 0, delta.Z).Magnitude > CFG.macroArriveRadius
            or math.abs(delta.Y) > 6 then
            break
        end
        MC.playCursor = MC.playCursor + 1
        MC.playProgressDistance = nil
    end

    -- Fire every action anchored at or before the sample we have reached. They
    -- go off in recorded order, so a click that came before a Q still does.
    local actions = macro.actions or {}
    while MC.playActionCursor <= #actions and actions[MC.playActionCursor].i < MC.playCursor do
        fireAction(actions[MC.playActionCursor].kind, humanoid)
        MC.playActionCursor = MC.playActionCursor + 1
    end

    if MC.playCursor > count then
        -- Anything left over fires at the end rather than being dropped.
        while MC.playActionCursor <= #actions do
            fireAction(actions[MC.playActionCursor].kind, humanoid)
            MC.playActionCursor = MC.playActionCursor + 1
        end
        heavyDebug("Macro", string.format("Finished '%s'.", macro.name))
        advanceToNextMacro()
        return true
    end

    -- Walk at the current sample directly: the recorded route is known to be
    -- walkable, so routing around it would be second-guessing the human who
    -- walked it.
    local target = samplePosition(macro, MC.playCursor)

    -- Facing: point the body the way it pointed when you recorded. faceTowards
    -- flattens to yaw, which is all a humanoid can do - it keeps its torso
    -- upright no matter where you look. The recorded pitch is kept in the file
    -- (see sampleAt) but is not applied to the body, because a body cannot
    -- express it.
    local look = CFG.macroFaceRecorded and sampleLook(macro.samples[MC.playCursor]) or nil
    if look then
        faceTowards(root, humanoid, rootPos + look * 12)
    else
        releaseFacing(humanoid)
    end
    if not NAV.lastIssuedMove
        or (NAV.lastIssuedMove - target).Magnitude > CFG.moveReissueThreshold then
        humanoid:MoveTo(target)
        NAV.lastIssuedMove = target
    end
    NAV.driving = true

    -- Stuck on one sample: skip it. A recorded route can be blocked by a door
    -- that is shut this run, or by having drifted below a ledge.
    local distance = (rootPos - target).Magnitude
    if not MC.playProgressDistance or distance < MC.playProgressDistance - 1.0 then
        MC.playProgressDistance = distance
        MC.playProgressTime = now
    elseif now - MC.playProgressTime >= CFG.macroGiveUpTime then
        MC.playCursor = MC.playCursor + 1
        MC.playSkips = MC.playSkips + 1
        MC.playProgressDistance = nil
        MC.playProgressTime = now
        humanoid.Jump = true
        if MC.playSkips >= CFG.macroSkipLimit then
            heavyDebug("Macro", string.format(
                "'%s' skipped %d samples in a row; giving up on it.", macro.name, MC.playSkips))
            advanceToNextMacro()
            return true
        end
        heavyDebugThrottled("macro_skip", 2.0, "Macro", string.format(
            "Stuck at sample %d/%d of '%s'; skipping ahead.", MC.playCursor, count, macro.name))
    end

    setMovementState(string.format("MACRO '%s' %d/%d", macro.name, MC.playCursor, count))
    return true
end

-- ---------------------------------------------------------------- bind + mode
local function setRecordBind(keyCode)
    MC.recordBind = keyCode
    MC.bindCapture = false
    heavyDebug("Macro", "Record bind set to " .. keyCode.Name .. ".")
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

-- "legacy" | "clone" | "macro". Legacy and Clone both fight and pathfind and
-- differ only in how they dodge; Macro replays a recording instead.
local function setMacroMode(mode)
    MC.mode = (mode == "macro" or mode == "clone") and mode or "legacy"
    S.setCloneActive(MC.mode == "clone")
    if MC.mode ~= "macro" then
        if MC.playing then stopPlayback("switched to legacy waypoints") end
        if MC.recording then stopRecording() end
        clearMacroRoute()
    else
        -- The free-fly editor belongs to the waypoint system; it has no meaning
        -- in macro mode and would only get in the way of recording.
        if NAV.pathEditEnabled then
            setPathEditEnabled(false)
            if S.setFreecamButtonState then S.setFreecamButtonState() end
        end
        renderMacroRoute(MC.playIndex)
    end
    heavyDebug("Macro", "Mode: " .. MC.mode)
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

-- The record bind, and bind capture, live on one always-on listener.
local function startMacroInput()
    table.insert(MC.connections, UserInputService.InputBegan:Connect(function(input, processed)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        if MC.bindCapture then
            -- Escape cancels rather than binding itself.
            if input.KeyCode == Enum.KeyCode.Escape then
                MC.bindCapture = false
                if S.refreshMacroPanel then S.refreshMacroPanel() end
                return
            end
            setRecordBind(input.KeyCode)
            return
        end
        -- `processed` is true while a textbox has focus, which is exactly when
        -- the bind must not fire.
        if not processed and input.KeyCode == MC.recordBind then
            toggleRecording()
        end
    end))
end

-- ---------------------------------------------------------------- config i/o
-- Macros are plain data already (arrays of numbers and short strings), so they
-- round-trip through JSON as they are. A long macro is thousands of samples, so
-- the coordinates were rounded to one decimal at record time.
local function serializeMacros()
    local out = {}
    for _, macro in ipairs(MC.macros) do
        table.insert(out, {
            name = macro.name,
            samples = macro.samples,
            actions = macro.actions,
            duration = macro.duration,
            recordedAt = macro.recordedAt,
        })
    end
    return out
end

local function loadMacros(list)
    table.clear(MC.macros)
    MC.playIndex = 1
    clearMacroRoute()
    if type(list) ~= "table" then return 0 end
    for _, macro in ipairs(list) do
        if type(macro) == "table" and type(macro.samples) == "table" and #macro.samples >= 2 then
            table.insert(MC.macros, {
                name = type(macro.name) == "string" and macro.name or ("Macro " .. (#MC.macros + 1)),
                samples = macro.samples,
                actions = type(macro.actions) == "table" and macro.actions or {},
                duration = tonumber(macro.duration) or 0,
                recordedAt = tonumber(macro.recordedAt) or 0,
            })
        end
    end
    if S.refreshMacroPanel then S.refreshMacroPanel() end
    return #MC.macros
end

-- Save the recordings you have open into ANY map's slot, not only the one you
-- happen to have selected: you record a route once and file it where it belongs.
local function saveMacrosToMap(code)
    RT.macroData[code] = serializeMacros()
    heavyDebug("Macro", string.format("Filed %d macro(s) under %s.", #MC.macros, code))
    if S.saveMacroFile then S.saveMacroFile() end
    if S.refreshMacroPanel then S.refreshMacroPanel() end
end

-- Load a map's recordings and start playing them. Switching map through
-- setCurrentMap keeps the waypoints and keep list in step too.
local function playMapMacros(code)
    if S.setCurrentMap then S.setCurrentMap(code) end
    if #MC.macros == 0 then
        heavyDebug("Macro", string.format("%s has no macros saved.", code))
        setMovementState("no macros for " .. code)
        return
    end
    setMacroMode("macro")
    playMacro(1)
end

local function stopMacroSubsystem()
    if MC.recording then MC.recording = false end
    MC.playing = false
    disconnectRecordInputs()
    for _, connection in ipairs(MC.connections) do connection:Disconnect() end
    table.clear(MC.connections)
    clearMacroRoute()
end

S.startRecording = startRecording
S.stopRecording = stopRecording
S.toggleRecording = toggleRecording
S.recordStep = recordStep
S.removeMacro = removeMacro
S.moveMacro = moveMacro
S.renameMacro = renameMacro
S.clearMacros = clearMacros
S.playMacro = playMacro
S.stopPlayback = stopPlayback
S.runMacroPlayback = runMacroPlayback
S.setRecordBind = setRecordBind
S.setMacroMode = setMacroMode
S.startMacroInput = startMacroInput
S.serializeMacros = serializeMacros
S.loadMacros = loadMacros
S.renderMacroRoute = renderMacroRoute
S.clearMacroRoute = clearMacroRoute
S.stopMacroSubsystem = stopMacroSubsystem
S.saveMacrosToMap = saveMacrosToMap
S.playMapMacros = playMapMacros
end
    end)()
    module(S)
end

-- ===================================== src/streamer.lua =====================================
do
    local module = (function()
-- streamer.lua - Streamer Mode: local cosmetic masking of the account identity.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local SM = S.SM
local heavyDebug = S.heavyDebug
local LocalPlayer = S.LocalPlayer
local RunService = S.RunService
local heavyDebugThrottled = S.heavyDebugThrottled
local UserInputService = S.UserInputService
local SCRIPT_VERSION = S.SCRIPT_VERSION

--[[ ===========================================================================
    STREAMER MODE

    Local cosmetic overlay for streaming: masks the account identity on screen.
    It rewrites what THIS client renders, nothing else. The server, other
    players, and every leaderboard still see the real account, so this hides
    your name on stream, it does not change your name in the game.

    The game's GUI hierarchy is unknown to this script, so targets are found by
    content rather than by path: any text showing the real username or display
    name is rewritten, any image sourced from the real user id is swapped. HP,
    EXP, level and VIP fields are matched by name keywords, and anything the
    keywords miss can be bound by hand with the row's bind button.
=========================================================================== ]]

SM.enabled = false
SM.connection = nil
SM.bindConnection = nil
SM.panel = nil
SM.statusLabel = nil

SM.fields = {
    username = "Streamer",
    hp = "",
    vipTitle = "",
    exp = "",
    level = "",
    coins = "",
    gems = "",
}

SM.vipColor = Color3.fromRGB(255, 200, 60)
SM.borderColor = Color3.fromRGB(255, 200, 60)
SM.levelColor = Color3.fromRGB(120, 190, 255)
SM.avatarImage = ""

-- [field] = { [instance] = true }. Populated by auto-detection and by binds.
SM.targets = {
    username = {},
    hp = {},
    vipTitle = {},
    exp = {},
    level = {},
    coins = {},
    gems = {},
    border = {},
    avatar = {},
}

SM.manualBinds = {}
SM.originals = {}
SM.pendingBindField = nil
SM.lastDiscoveryTime = -math.huge
SM.discoveryInterval = 1.5
SM.applyInterval = 0.12
SM.lastApplyTime = -math.huge

-- Text that identifies a developer/telemetry overlay worth hiding on stream.
-- A container is hidden when at least two of these appear beneath it, so a
-- single label that merely mentions "position" is not enough to trigger it.
SM.debugOverlayPhrases = {
    "world position", "data loaded", "place version", "server age",
    "server region", "job id", "jobid", "instance id", "session id",
    "client version", "build id", "user id", "userid", "account age",
}

SM.hiddenElements = {}
SM.autoHideOverlays = true

-- [instance] = { connections } watching Text/Image so an override is reasserted
-- the instant the game writes, rather than on the next poll.
SM.signalConnections = {}
-- Set by the panel so a config-driven enable can update the toggle's own label.
SM.syncToggleWidget = nil
-- Re-entrancy guard: writing Text refires the same signal we are handling.
SM.applyingTo = {}

-- Forward declaration; defined once applyBorderColorTo is available.
local applyToTarget

SM.fieldKeywords = {
    hp = { "hp", "health", "hitpoint" },
    exp = { "exp", "xp", "experience" },
    level = { "level", "lvl", "rank" },
    vipTitle = { "vip", "title", "tag", "premium", "badge" },
    coins = { "coin", "gold", "cash", "money", "currency" },
    gems = { "gem", "diamond", "crystal", "robux" },
}

local function parseHexColor(text)
    if type(text) ~= "string" then return nil end
    local hex = text:gsub("#", ""):gsub("%s", "")
    if #hex ~= 6 then return nil end
    local r = tonumber(hex:sub(1, 2), 16)
    local g = tonumber(hex:sub(3, 4), 16)
    local b = tonumber(hex:sub(5, 6), 16)
    if not r or not g or not b then return nil end
    return Color3.fromRGB(r, g, b)
end

local function toHexString(color)
    return string.format("%02X%02X%02X",
        math.floor(color.R * 255 + 0.5),
        math.floor(color.G * 255 + 0.5),
        math.floor(color.B * 255 + 0.5))
end

-- Roblox cannot upload an image from a script. Accepts an asset id, an
-- rbxassetid:// string, or a roblox.com URL, and normalises to rbxassetid://.
local function normalizeImageId(text)
    if type(text) ~= "string" then return "" end
    local digits = text:match("(%d+)")
    if not digits then return "" end
    return "rbxassetid://" .. digits
end

local function isTextObject(obj)
    return obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")
end

local function isImageObject(obj)
    return obj:IsA("ImageLabel") or obj:IsA("ImageButton")
end

local function rememberStreamerOriginal(obj)
    if SM.originals[obj] then return end
    local snapshot = {}
    if isTextObject(obj) then
        snapshot.Text = obj.Text
        snapshot.TextColor3 = obj.TextColor3
    end
    if isImageObject(obj) then
        snapshot.Image = obj.Image
        snapshot.ImageColor3 = obj.ImageColor3
    end
    if obj:IsA("UIStroke") then
        snapshot.StrokeColor = obj.Color
    end
    if obj:IsA("GuiObject") then
        snapshot.BorderColor3 = obj.BorderColor3
        snapshot.BackgroundColor3 = obj.BackgroundColor3
    end
    SM.originals[obj] = snapshot
end

-- Registers a target and starts watching it. The watch is what removes the
-- flicker: polling every 0.12s meant the game's own write (on an EXP tick, a
-- damage number, a stat refresh) was visible until the next poll came round.
-- Reacting to the property signal puts the correction in the same frame.
local function registerStreamerTarget(field, obj)
    local set = SM.targets[field]
    if not set or set[obj] then return end

    set[obj] = true
    rememberStreamerOriginal(obj)

    if not SM.signalConnections[obj] then
        local connections = {}

        local function watch(property)
            local ok, signal = pcall(function()
                return obj:GetPropertyChangedSignal(property)
            end)
            if ok and signal then
                table.insert(connections, signal:Connect(function()
                    if SM.enabled then
                        applyToTarget(field, obj)
                    end
                end))
            end
        end

        if isTextObject(obj) then watch("Text") end
        if isImageObject(obj) then watch("Image") end

        SM.signalConnections[obj] = connections
    end

    if SM.enabled then
        applyToTarget(field, obj)
    end
end

local function unwatchStreamerTarget(obj)
    local connections = SM.signalConnections[obj]
    if not connections then return end
    for _, connection in ipairs(connections) do
        connection:Disconnect()
    end
    SM.signalConnections[obj] = nil
end

local function unwatchAllStreamerTargets()
    for obj in pairs(SM.signalConnections) do
        unwatchStreamerTarget(obj)
    end
    table.clear(SM.signalConnections)
    table.clear(SM.applyingTo)
end

-- Most nametags draw their "border" as a gold Frame sitting behind a slightly
-- smaller inner Frame, not as a UIStroke. Detecting by class alone therefore
-- missed it entirely, so trim is identified by colour instead: warm golds and
-- yellows, where red and green are both strong and clearly above blue.
-- The green HP fill, the cream badge backing and dark panels all fail this.
local function isTrimColor(color)
    return color.R >= 0.55
        and color.G >= 0.38
        and color.B <= 0.55
        and color.R >= color.G
        and (color.G - color.B) >= 0.15
end

-- Collects the trim pieces of any nametag billboard in `container`. Scoped to
-- billboards so a gold element elsewhere in the HUD is never repainted.
local function collectNametagTrim(container, character)
    for _, obj in ipairs(container:GetDescendants()) do
        local billboard = obj:FindFirstAncestorOfClass("BillboardGui")
        if billboard then
            -- Billboards living outside the character only count when they are
            -- adorned to it, so other players' nametags are left alone.
            local ownsIt = character and (billboard:IsDescendantOf(character)
                or (billboard.Adornee and billboard.Adornee:IsDescendantOf(character)))

            if ownsIt then
                local isTrim = false

                if obj:IsA("UIStroke") then
                    isTrim = true
                elseif obj:IsA("GuiObject") and not isTextObject(obj) then
                    if obj.BackgroundTransparency < 0.95 and isTrimColor(obj.BackgroundColor3) then
                        isTrim = true
                    elseif isImageObject(obj) and obj.ImageTransparency < 0.95 and isTrimColor(obj.ImageColor3) then
                        isTrim = true
                    end
                end

                if isTrim then
                    registerStreamerTarget("border", obj)
                end
            end
        end
    end
end

-- The gold trim on the nametag can be a UIStroke, a bordered frame, or a plain
-- coloured backing frame depending on how the game built it, so all three are
-- handled and the most specific one wins.
local function applyBorderColorTo(obj, color)
    if obj:IsA("UIStroke") then
        obj.Color = color
        return
    end

    -- Ordered so the property that is actually drawing the trim wins. A visible
    -- background is what the colour detection matched on, so it takes priority
    -- over a stroke the element may also happen to carry.
    if isImageObject(obj) and obj.Image ~= "" and obj.ImageTransparency < 0.95 then
        obj.ImageColor3 = color
        return
    end

    if obj:IsA("GuiObject") then
        if obj.BackgroundTransparency < 0.95 then
            obj.BackgroundColor3 = color
            return
        end
        if obj.BorderSizePixel > 0 then
            obj.BorderColor3 = color
            return
        end
        local stroke = obj:FindFirstChildOfClass("UIStroke")
        if stroke then
            rememberStreamerOriginal(stroke)
            stroke.Color = color
        end
    end
end

local function nameMatchesKeywords(obj, keywords)
    local node = obj
    local depth = 0
    while node and depth < 4 do
        local lowered = string.lower(node.Name)
        for _, word in ipairs(keywords) do
            if string.find(lowered, word, 1, true) then
                return true
            end
        end
        node = node.Parent
        depth = depth + 1
    end
    return false
end

-- Targets are sticky: only destroyed instances are dropped. Detection is by
-- content, so a label already showing the fake name no longer matches the real
-- one; forgetting it would let the real name flash back for up to one discovery
-- interval whenever the game rewrote that label.
local function pruneDeadStreamerTargets()
    for obj in pairs(SM.hiddenElements) do
        if not obj.Parent then
            SM.hiddenElements[obj] = nil
        end
    end

    for _, set in pairs(SM.targets) do
        for obj in pairs(set) do
            if not obj.Parent then
                set[obj] = nil
                SM.originals[obj] = nil
                SM.manualBinds[obj] = nil
                unwatchStreamerTarget(obj)
            end
        end
    end
end

local function scanContainerForStreamerTargets(container, realName, realDisplay, realUserId)
    for _, obj in ipairs(container:GetDescendants()) do
        local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
        if not isOurs then
            if isTextObject(obj) then
                local text = obj.Text
                if text ~= "" then
                    if string.find(text, realName, 1, true)
                        or (realDisplay ~= realName and string.find(text, realDisplay, 1, true)) then
                        registerStreamerTarget("username", obj)
                    end

                    for field, keywords in pairs(SM.fieldKeywords) do
                        if SM.fields[field] ~= "" and nameMatchesKeywords(obj, keywords) then
                            registerStreamerTarget(field, obj)
                        end
                    end
                end
            elseif isImageObject(obj) then
                if string.find(obj.Image, realUserId, 1, true) then
                    registerStreamerTarget("avatar", obj)
                end
            end
        end
    end
end

local function hideStreamerElement(obj, reason)
    if not obj or SM.hiddenElements[obj] then return end
    if RT.scriptGui and obj:IsDescendantOf(RT.scriptGui) then return end
    if not obj:IsA("GuiObject") then return end

    SM.hiddenElements[obj] = obj.Visible
    obj.Visible = false
    heavyDebug("Streamer", string.format("Hid '%s' (%s) - %s", obj.Name, obj.ClassName, reason))
end

local function restoreHiddenElements()
    for obj, wasVisible in pairs(SM.hiddenElements) do
        if obj.Parent then
            pcall(function() obj.Visible = wasVisible end)
        end
    end
    table.clear(SM.hiddenElements)
end

-- Finds telemetry overlays like the World Position / Data Loaded / Place Version
-- / Server Age readout and hides the container holding them, rather than each
-- row, so no empty frame is left behind.
local function hideDebugOverlays(playerGui)
    if not SM.autoHideOverlays then return end

    local matchCounts = {}

    for _, obj in ipairs(playerGui:GetDescendants()) do
        local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
        if not isOurs and isTextObject(obj) and obj.Text ~= "" then
            local lowered = string.lower(obj.Text)
            local matched = false
            for _, phrase in ipairs(SM.debugOverlayPhrases) do
                if string.find(lowered, phrase, 1, true) then
                    matched = true
                    break
                end
            end

            if matched then
                -- Credit the label and its nearby ancestors, so the shared
                -- container accumulates the highest count.
                local node = obj
                local depth = 0
                while node and depth < 5 and not node:IsA("ScreenGui") do
                    matchCounts[node] = (matchCounts[node] or 0) + 1
                    node = node.Parent
                    depth = depth + 1
                end
            end
        end
    end

    for node, count in pairs(matchCounts) do
        if count >= 2 and node:IsA("GuiObject") then
            -- Hide the outermost container that still holds every match, so the
            -- whole readout goes at once.
            local best = node
            local walker = node.Parent
            local depth = 0
            while walker and depth < 4 and walker:IsA("GuiObject") do
                if (matchCounts[walker] or 0) == count then
                    best = walker
                end
                walker = walker.Parent
                depth = depth + 1
            end
            hideStreamerElement(best, string.format("telemetry overlay, %d matches", count))
        end
    end
end

-- Applies one field to one element. Split out of the bulk apply so a property
-- signal can correct a single label immediately without sweeping everything.
applyToTarget = function(field, obj)
    if not obj.Parent or SM.applyingTo[obj] then return end
    SM.applyingTo[obj] = true

    if field == "border" then
        applyBorderColorTo(obj, SM.borderColor)

    elseif field == "avatar" then
        if SM.avatarImage ~= "" and isImageObject(obj) and obj.Image ~= SM.avatarImage then
            obj.Image = SM.avatarImage
        end

    elseif field == "username" then
        if isTextObject(obj) then
            local realName = LocalPlayer.Name
            local realDisplay = LocalPlayer.DisplayName or realName
            local fakeName = SM.fields.username ~= "" and SM.fields.username or "Streamer"
            local current = obj.Text
            local replaced = string.gsub(current, realName, fakeName)
            if realDisplay ~= realName then
                replaced = string.gsub(replaced, realDisplay, fakeName)
            end
            if replaced ~= current then
                obj.Text = replaced
            end
        end

    else
        local value = SM.fields[field]
        if value and value ~= "" and isTextObject(obj) then
            if obj.Text ~= value then
                obj.Text = value
            end
            if field == "vipTitle" then
                obj.TextColor3 = SM.vipColor
            elseif field == "level" then
                obj.TextColor3 = SM.levelColor
            end
        end
    end

    SM.applyingTo[obj] = nil
end

-- Full path from the DataModel, so a reported element can be located exactly.
local function describeInstancePath(obj)
    local segments = {}
    local node = obj
    local depth = 0
    while node and node ~= game and depth < 12 do
        table.insert(segments, 1, node.Name)
        node = node.Parent
        depth = depth + 1
    end
    return table.concat(segments, ".")
end

-- Prints every GUI element that looks identity-bearing, with its path, class and
-- current text. Run it, copy the console, and the matching rules can be widened
-- to whatever this particular game actually uses.
local function dumpStreamerCandidates()
    local realName = LocalPlayer.Name
    local realDisplay = LocalPlayer.DisplayName or realName
    local realUserId = tostring(LocalPlayer.UserId)

    print(string.rep("=", 78))
    print(string.format("  STREAMER GUI DUMP  |  v%s  |  account: %s (display '%s', id %s)",
        SCRIPT_VERSION, realName, realDisplay, realUserId))
    print(string.rep("=", 78))

    local total = 0

    local function dumpContainer(container, containerLabel)
        if not container then return end
        print(string.format("--- %s ---", containerLabel))
        local found = 0

        for _, obj in ipairs(container:GetDescendants()) do
            local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
            if not isOurs then
                local reasons = nil

                local function note(tag)
                    reasons = reasons or {}
                    table.insert(reasons, tag)
                end

                if isTextObject(obj) and obj.Text ~= "" then
                    local text = obj.Text
                    local lowered = string.lower(text)

                    if string.find(text, realName, 1, true) then note("USERNAME") end
                    if realDisplay ~= realName and string.find(text, realDisplay, 1, true) then note("DISPLAYNAME") end
                    -- Value shapes visible in the HUD: "5.30M/5.30M", "129.84M/3.69B",
                    -- "5307855/5307855", a bare level number, and VIP/title text.
                    if string.match(text, "^%s*[%d%.,]+[KMBT]?%s*/%s*[%d%.,]+[KMBT]?%s*$") then note("PAIR_VALUE") end
                    if string.match(text, "^%s*%d+%s*$") then note("BARE_NUMBER") end
                    if string.find(lowered, "hp", 1, true) or string.find(lowered, "health", 1, true) then note("HP_TEXT") end
                    if string.find(lowered, "exp", 1, true) then note("EXP_TEXT") end
                    if string.find(lowered, "vip", 1, true) then note("VIP_TEXT") end
                    if string.match(text, "^%s*%b()%s*$") then note("PARENTHESISED") end

                    for field, keywords in pairs(SM.fieldKeywords) do
                        if nameMatchesKeywords(obj, keywords) then note("NAMEHINT:" .. field) end
                    end

                    if reasons then
                        found = found + 1
                        total = total + 1
                        print(string.format("[%s] %s", table.concat(reasons, ","), obj.ClassName))
                        print(string.format("    text : %q", text))
                        print(string.format("    path : %s", describeInstancePath(obj)))
                    end
                elseif isImageObject(obj) and obj.Image ~= "" then
                    if string.find(obj.Image, realUserId, 1, true) then
                        found = found + 1
                        total = total + 1
                        print(string.format("[AVATAR] %s", obj.ClassName))
                        print(string.format("    image: %s", obj.Image))
                        print(string.format("    path : %s", describeInstancePath(obj)))
                    end
                end
            end
        end

        if found == 0 then
            print("  (nothing matched here)")
        end
    end

    dumpContainer(LocalPlayer:FindFirstChildOfClass("PlayerGui"), "PlayerGui")
    dumpContainer(LocalPlayer.Character, "Character (nametag billboards)")

    print("--- nametag trim currently detected ---")
    local trimCount = 0
    for obj in pairs(SM.targets.border) do
        if obj.Parent then
            trimCount = trimCount + 1
            local swatch
            if obj:IsA("UIStroke") then
                swatch = "stroke " .. toHexString(obj.Color)
            elseif isImageObject(obj) and obj.Image ~= "" and obj.ImageTransparency < 0.95 then
                swatch = "image tint " .. toHexString(obj.ImageColor3)
            elseif obj:IsA("GuiObject") and obj.BackgroundTransparency < 0.95 then
                swatch = "background " .. toHexString(obj.BackgroundColor3)
            else
                swatch = "border " .. toHexString(obj.BorderColor3)
            end
            print(string.format("[TRIM] %s (%s)", obj.ClassName, swatch))
            print(string.format("    path : %s", describeInstancePath(obj)))
        end
    end
    if trimCount == 0 then
        print("  (none detected - use the trim row's bind button and click the border)")
    end

    print(string.rep("=", 78))
    print(string.format("  %d candidate elements, %d trim pieces.", total, trimCount))
    print(string.rep("=", 78))

    return total
end

local function discoverStreamerTargets()
    local realName = LocalPlayer.Name
    local realDisplay = LocalPlayer.DisplayName or realName
    local realUserId = tostring(LocalPlayer.UserId)

    pruneDeadStreamerTargets()

    local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if playerGui then
        scanContainerForStreamerTargets(playerGui, realName, realDisplay, realUserId)
        hideDebugOverlays(playerGui)
    end

    -- Character descendants carry the overhead nametag billboards.
    local character = LocalPlayer.Character
    if character then
        scanContainerForStreamerTargets(character, realName, realDisplay, realUserId)

        collectNametagTrim(character, character)
    end

    -- Some games parent the nametag billboard into PlayerGui and adorn it to the
    -- head instead of nesting it under the character, so check there too. The
    -- adornee test keeps other players' nametags out of it.
    if playerGui and character then
        collectNametagTrim(playerGui, character)
    end

    for obj, field in pairs(SM.manualBinds) do
        if obj.Parent then
            registerStreamerTarget(field, obj)
        else
            SM.manualBinds[obj] = nil
        end
    end
end

local function applyStreamerOverlay()
    for field, set in pairs(SM.targets) do
        for obj in pairs(set) do
            applyToTarget(field, obj)
        end
    end
end

local function restoreStreamerOriginals()
    for obj, snapshot in pairs(SM.originals) do
        if obj.Parent then
            pcall(function()
                if snapshot.Text ~= nil and isTextObject(obj) then
                    obj.Text = snapshot.Text
                    obj.TextColor3 = snapshot.TextColor3
                end
                if snapshot.Image ~= nil and isImageObject(obj) then
                    obj.Image = snapshot.Image
                    obj.ImageColor3 = snapshot.ImageColor3
                end
                if snapshot.StrokeColor ~= nil and obj:IsA("UIStroke") then
                    obj.Color = snapshot.StrokeColor
                end
                if snapshot.BorderColor3 ~= nil and obj:IsA("GuiObject") then
                    obj.BorderColor3 = snapshot.BorderColor3
                    obj.BackgroundColor3 = snapshot.BackgroundColor3
                end
            end)
        end
    end
    table.clear(SM.originals)
end

local function setStreamerStatus(text)
    if SM.statusLabel then
        SM.statusLabel.Text = text
    end
end

local function countStreamerTargets()
    local total = 0
    for _, set in pairs(SM.targets) do
        for _ in pairs(set) do
            total = total + 1
        end
    end
    return total
end

local function setStreamerEnabled(enabled)
    SM.enabled = enabled

    if SM.connection then
        SM.connection:Disconnect()
        SM.connection = nil
    end

    if not enabled then
        unwatchAllStreamerTargets()
        restoreStreamerOriginals()
        restoreHiddenElements()
        for field in pairs(SM.targets) do
            SM.targets[field] = {}
        end
        setStreamerStatus("Off. Original display restored.")
        heavyDebug("Streamer", "Streamer mode disabled, originals restored.")
        return
    end

    discoverStreamerTargets()
    applyStreamerOverlay()
    SM.lastDiscoveryTime = os.clock()
    setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
    heavyDebug("Streamer", string.format("Streamer mode enabled. %d elements masked.", countStreamerTargets()))

    -- The game rewrites its own labels, so the overlay has to be reasserted.
    -- Both clocks are deliberately slow; this is cosmetic and must not cost frames.
    SM.connection = RunService.Heartbeat:Connect(function()
        if RT.destroyed or not SM.enabled then return end
        local clock = os.clock()

        if clock - SM.lastApplyTime >= SM.applyInterval then
            SM.lastApplyTime = clock
            local ok, err = xpcall(applyStreamerOverlay, debug.traceback)
            if not ok then
                heavyDebugThrottled("streamer_apply_err", 2.0, "FATAL", "Streamer overlay threw:\n" .. tostring(err))
            end
        end

        if clock - SM.lastDiscoveryTime >= SM.discoveryInterval then
            SM.lastDiscoveryTime = clock
            local ok, err = xpcall(discoverStreamerTargets, debug.traceback)
            if not ok then
                heavyDebugThrottled("streamer_scan_err", 2.0, "FATAL", "Streamer discovery threw:\n" .. tostring(err))
            else
                setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
            end
        end
    end)
end

local function refreshStreamerOverlay()
    if not SM.enabled then return end
    discoverStreamerTargets()
    applyStreamerOverlay()
    setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
end

-- Bind mode: the next GUI click assigns that element to the pending field, for
-- anything the keyword matching did not find.
local function setPendingBindField(field)
    SM.pendingBindField = field

    if SM.bindConnection then
        SM.bindConnection:Disconnect()
        SM.bindConnection = nil
    end

    if not field then return end

    setStreamerStatus("Bind armed: click the " .. field .. " element on screen.")

    SM.bindConnection = UserInputService.InputBegan:Connect(function(input, processed)
        if not SM.pendingBindField then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return end

        local inset = game:GetService("GuiService"):GetGuiInset()
        local position = UserInputService:GetMouseLocation()
        local candidates = playerGui:GetGuiObjectsAtPosition(position.X - inset.X, position.Y - inset.Y)

        for _, obj in ipairs(candidates) do
            local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
            if not isOurs and SM.pendingBindField == "hide" and obj:IsA("GuiObject") then
                hideStreamerElement(obj, "hidden by hand")
                setStreamerStatus(string.format("Hid '%s'.", obj.Name))
                setPendingBindField(nil)
                return
            end

            if not isOurs and SM.pendingBindField == "border" and obj:IsA("GuiObject") then
                SM.manualBinds[obj] = "border"
                registerStreamerTarget("border", obj)
                setStreamerStatus(string.format("Bound '%s' as nametag trim.", obj.Name))
                setPendingBindField(nil)
                applyStreamerOverlay()
                return
            end

            if not isOurs and (isTextObject(obj) or isImageObject(obj)) then
                local field = SM.pendingBindField
                SM.manualBinds[obj] = field
                registerStreamerTarget(field, obj)
                heavyDebug("Streamer", string.format("Bound '%s' (%s) to field '%s'.",
                    obj.Name, obj.ClassName, field))
                setStreamerStatus(string.format("Bound '%s' to %s.", obj.Name, field))
                setPendingBindField(nil)
                applyStreamerOverlay()
                return
            end
        end

        setStreamerStatus("Nothing bindable under the cursor. Try again.")
    end)
end

S.describeInstancePath = describeInstancePath
S.dumpStreamerCandidates = dumpStreamerCandidates
S.normalizeImageId = normalizeImageId
S.parseHexColor = parseHexColor
S.refreshStreamerOverlay = refreshStreamerOverlay
S.restoreHiddenElements = restoreHiddenElements
S.setPendingBindField = setPendingBindField
S.setStreamerEnabled = setStreamerEnabled
S.setStreamerStatus = setStreamerStatus
S.toHexString = toHexString
end
    end)()
    module(S)
end

-- ===================================== src/config.lua =====================================
do
    local module = (function()
-- config.lua - JSON config persistence through the executor's file API.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local SM = S.SM
local describeInstancePath = S.describeInstancePath
local HZ = S.HZ
local NAV = S.NAV
local CFG = S.CFG
local toHexString = S.toHexString
local heavyDebug = S.heavyDebug
local parseHexColor = S.parseHexColor
local renderPathMarkers = S.renderPathMarkers
local SCRIPT_VERSION = S.SCRIPT_VERSION

--[[ ===========================================================================
    CONFIG PERSISTENCE

    Uses the executor's writefile/readfile, which are not part of Roblox itself,
    so every call is guarded and the script stays functional without them.

    Manual binds are stored as instance paths rather than references, and
    re-resolved by name on load. Paths are the fragile part: a game that renames
    or restructures its GUI between sessions will simply fail to resolve those
    entries, which is why a failed resolve is skipped quietly rather than
    treated as an error.
=========================================================================== ]]

local LD = S.LD
local MC = S.MC
local MAP_LABELS = S.MAP_LABELS
local refreshLowDetail = S.refreshLowDetail
local serializeMacros = S.serializeMacros
local loadMacros = S.loadMacros

local CONFIG_FILE = "DungeonAutofarm_config.json"

local function hasFileAccess()
    return type(writefile) == "function"
        and type(readfile) == "function"
        and type(isfile) == "function"
end

local function resolveInstancePath(path)
    local node = game
    for segment in string.gmatch(path, "[^%.]+") do
        if node == game and segment == "game" then
            -- Leading "game" is part of the recorded path; skip it.
        else
            local nextNode = node:FindFirstChild(segment)
            if not nextNode then return nil end
            node = nextNode
        end
    end
    return node ~= game and node or nil
end

-- =========================================================================
-- PER-MAP STORAGE (2.4.0)
--
-- The waypoint path and the low-detail keep list are properties of a dungeon,
-- not of the session, so they are stored per map code. RT.mapData holds every
-- map the config knows about; the live NAV.waypath / LD.keepNames are just the
-- selected map's entry checked out for editing. Switching map checks the
-- current one back in and the new one out.
-- =========================================================================

local function syncCurrentMapToStore()
    local waypath = {}
    for _, pos in ipairs(NAV.waypath) do
        table.insert(waypath, { x = pos.X, y = pos.Y, z = pos.Z })
    end
    local keep = {}
    for name in pairs(LD.keepNames) do
        table.insert(keep, name)
    end
    RT.mapData[RT.currentMap] = { waypath = waypath, keep = keep }
    -- Macros are bulky and live in their own file; the map store only carries
    -- the light data.
    RT.macroData[RT.currentMap] = serializeMacros()
end

-- =========================================================================
-- The macro file. Separate from the config because a single ten-minute
-- recording is thousands of samples, and keeping it apart means the config
-- stays small and hand-editable while the macros stay easy to copy between
-- machines or hand to someone else.
-- =========================================================================
local function saveMacroFile()
    if not hasFileAccess() then return false, "no file access in this executor" end
    local ok, err = pcall(function()
        local payload = { version = SCRIPT_VERSION, maps = RT.macroData }
        writefile(CFG.macroFile, game:GetService("HttpService"):JSONEncode(payload))
    end)
    if ok then
        local total = 0
        for _, list in pairs(RT.macroData) do total = total + #list end
        heavyDebug("Config", string.format("Saved %d macro(s) to %s.", total, CFG.macroFile))
        return true
    end
    heavyDebug("Config", "Macro save failed: " .. tostring(err))
    return false, tostring(err)
end

local function loadMacroFile()
    if not hasFileAccess() then return false end
    local exists = false
    pcall(function() exists = isfile(CFG.macroFile) end)
    if not exists then return false end

    local data
    local ok = pcall(function()
        data = game:GetService("HttpService"):JSONDecode(readfile(CFG.macroFile))
    end)
    if not ok or type(data) ~= "table" or type(data.maps) ~= "table" then
        heavyDebug("Config", "Macro file unreadable; starting with none.")
        return false
    end

    table.clear(RT.macroData)
    local total = 0
    for code, list in pairs(data.maps) do
        if MAP_LABELS[code] and type(list) == "table" then
            RT.macroData[code] = list
            total = total + #list
        end
    end
    heavyDebug("Config", string.format("Loaded %d macro(s) across %d map(s) from %s.",
        total, (function() local c = 0 for _ in pairs(RT.macroData) do c = c + 1 end return c end)(),
        CFG.macroFile))
    return true
end

-- Checks a map's stored data out into the live tables. Does NOT save.
local function applyMapFromStore(code)
    local entry = RT.mapData[code] or {}

    table.clear(NAV.waypath)
    if type(entry.waypath) == "table" then
        for _, p in ipairs(entry.waypath) do
            if type(p) == "table" and tonumber(p.x) and tonumber(p.y) and tonumber(p.z) then
                table.insert(NAV.waypath, Vector3.new(p.x, p.y, p.z))
            end
        end
    end
    NAV.pathIndex = 1
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end

    table.clear(LD.keepNames)
    if type(entry.keep) == "table" then
        for _, name in ipairs(entry.keep) do
            if type(name) == "string" then LD.keepNames[name] = true end
        end
    end
    refreshLowDetail()
    if S.refreshMapPanel then S.refreshMapPanel() end

    local macroCount = loadMacros(RT.macroData[code])

    local keepCount = 0
    for _ in pairs(LD.keepNames) do keepCount = keepCount + 1 end
    heavyDebug("Map", string.format("%s (%s): %d waypoint(s), %d macro(s), %d kept part name(s).",
        code, MAP_LABELS[code] or code, #NAV.waypath, macroCount, keepCount))
end

-- The map picker. Checks the current map in, then the requested one out.
local function setCurrentMap(code)
    if not MAP_LABELS[code] or code == RT.currentMap then
        if code == RT.currentMap then applyMapFromStore(code) end
        return
    end
    syncCurrentMapToStore()
    RT.currentMap = code
    applyMapFromStore(code)
end

local function buildConfigTable()
    local binds = {}
    for obj, field in pairs(SM.manualBinds) do
        if obj.Parent then
            table.insert(binds, { path = describeInstancePath(obj), field = field })
        end
    end

    local learned = {}
    for name in pairs(HZ.learnedNames) do
        table.insert(learned, name)
    end

    -- Names learned as our own ability effects (2.2.0), so they are recognised
    -- on sight next session without waiting for the timing signal again.
    local ownNames = {}
    for name in pairs(HZ.ownNames) do
        table.insert(ownNames, name)
    end

    -- Per-map storage (2.4.0). The live waypath and keep list belong to whichever
    -- map is selected; everything already loaded for the other maps is carried
    -- through untouched, so saving one dungeon never drops the rest.
    syncCurrentMapToStore()
    local maps = {}
    for code, entry in pairs(RT.mapData) do
        maps[code] = entry
    end

    return {
        version = SCRIPT_VERSION,
        combat = {
            attackRange = CFG.attackRange,
            safeDistance = CFG.safeDistance,
            wallPadding = CFG.wallPadding,
            damageBrickDetectionRange = CFG.damageBrickDetectionRange,
            autoQ = RT.autoQEnabled,
            autoE = RT.autoEEnabled,
            faceTarget = CFG.faceTarget,
            followPath = CFG.followPath,
            loopPath = CFG.loopPath,
            waypointClearRadius = CFG.waypointClearRadius,
            macroMode = MC.mode,
            cloneCount = CFG.cloneCount,
            cloneRings = CFG.cloneRings,
            cloneRadius = CFG.cloneRadius,
            cloneSafetyMargin = CFG.cloneSafetyMargin,
            cloneCommitTime = CFG.cloneCommitTime,
            showClones = CFG.showClones,
            macroLoop = CFG.macroLoop,
            macroShowRoute = CFG.macroShowRoute,
            macroRecordBind = MC.recordBind.Name,
            abilityRadiusEnabled = CFG.abilityRadiusEnabled,
            abilityRadius = CFG.abilityRadius,
            showAbilityRadius = CFG.showAbilityRadius,
            recoveryEnabled = CFG.recoveryEnabled,
        },
        visuals = {
            renderPath = RT.renderPathEnabled,
            renderHazards = RT.renderHazardsEnabled,
            renderHitbox = RT.renderHitboxEnabled,
            showWalls = CFG.showWalls,
            panelAutofarm = CFG.panelAutofarm,
            panelRoutes = CFG.panelRoutes,
            panelAccount = CFG.panelAccount,
            panelConfigs = CFG.panelConfigs,
            debugLevel = RT.debugLevel,
        },
        streamer = {
            enabled = SM.enabled,
            fields = SM.fields,
            vipColor = toHexString(SM.vipColor),
            levelColor = toHexString(SM.levelColor),
            borderColor = toHexString(SM.borderColor),
            avatarImage = SM.avatarImage,
            autoHideOverlays = SM.autoHideOverlays,
            binds = binds,
        },
        learnedTelegraphNames = learned,
        ownAttackNames = ownNames,
        -- Plain data by construction (partSignature + name/hits/flags), so it
        -- round-trips through JSON as-is.
        attackBook = HZ.attackBook,
        currentMap = RT.currentMap,
        maps = maps,
    }
end

local function saveConfig()
    if not hasFileAccess() then
        heavyDebug("Config", "Executor exposes no writefile; cannot save.")
        return false, "no file access in this executor"
    end

    local ok, err = pcall(function()
        local json = game:GetService("HttpService"):JSONEncode(buildConfigTable())
        writefile(CONFIG_FILE, json)
    end)

    if ok then
        heavyDebug("Config", "Saved to " .. CONFIG_FILE)
        saveMacroFile()
        return true
    end

    heavyDebug("Config", "Save failed: " .. tostring(err))
    return false, tostring(err)
end

-- Returns applied, message. Widgets are refreshed by the caller, which owns them.
-- The apply half of a config load, split out (2.10.0) so a stored profile can
-- be applied without a file read behind it: loadConfig reads the file and hands
-- the decoded table here, and the Configs panel hands it one it already had.
-- Returns whether Streamer Mode should come up enabled.
local function applyConfigData(data)
    local combat = data.combat
    if type(combat) == "table" then
        CFG.attackRange = tonumber(combat.attackRange) or CFG.attackRange
        CFG.safeDistance = tonumber(combat.safeDistance) or CFG.safeDistance
        CFG.wallPadding = tonumber(combat.wallPadding) or CFG.wallPadding
        CFG.damageBrickDetectionRange = tonumber(combat.damageBrickDetectionRange) or CFG.damageBrickDetectionRange
        RT.autoQEnabled = combat.autoQ == true
        RT.autoEEnabled = combat.autoE == true
        if combat.faceTarget ~= nil then
            CFG.faceTarget = combat.faceTarget == true
        end
        if combat.followPath ~= nil then
            CFG.followPath = combat.followPath == true
        end
        if combat.loopPath ~= nil then
            CFG.loopPath = combat.loopPath == true
        end
        CFG.waypointClearRadius = tonumber(combat.waypointClearRadius) or CFG.waypointClearRadius
        if combat.abilityRadiusEnabled ~= nil then
            CFG.abilityRadiusEnabled = combat.abilityRadiusEnabled == true
        end
        CFG.abilityRadius = tonumber(combat.abilityRadius) or CFG.abilityRadius
        if combat.showAbilityRadius ~= nil then
            CFG.showAbilityRadius = combat.showAbilityRadius == true
        end
        if combat.recoveryEnabled ~= nil then
            CFG.recoveryEnabled = combat.recoveryEnabled == true
        end
        if combat.macroMode == "macro" or combat.macroMode == "legacy"
            or combat.macroMode == "clone" then
            MC.mode = combat.macroMode
        end
        CFG.cloneCount = tonumber(combat.cloneCount) or CFG.cloneCount
        CFG.cloneRings = tonumber(combat.cloneRings) or CFG.cloneRings
        CFG.cloneRadius = tonumber(combat.cloneRadius) or CFG.cloneRadius
        CFG.cloneSafetyMargin = tonumber(combat.cloneSafetyMargin) or CFG.cloneSafetyMargin
        CFG.cloneCommitTime = tonumber(combat.cloneCommitTime) or CFG.cloneCommitTime
        if combat.showClones ~= nil then CFG.showClones = combat.showClones == true end
        if combat.macroLoop ~= nil then CFG.macroLoop = combat.macroLoop == true end
        if combat.macroShowRoute ~= nil then CFG.macroShowRoute = combat.macroShowRoute == true end
        if type(combat.macroRecordBind) == "string" then
            -- Enum.KeyCode[name] throws on a bad name rather than returning nil.
            local ok, keyCode = pcall(function() return Enum.KeyCode[combat.macroRecordBind] end)
            if ok and keyCode then MC.recordBind = keyCode end
        end
    end

    local visuals = data.visuals
    if type(visuals) == "table" then
        if visuals.renderPath ~= nil then RT.renderPathEnabled = visuals.renderPath == true end
        if visuals.renderHazards ~= nil then RT.renderHazardsEnabled = visuals.renderHazards == true end
        if visuals.renderHitbox ~= nil then RT.renderHitboxEnabled = visuals.renderHitbox == true end
        if visuals.showWalls ~= nil then CFG.showWalls = visuals.showWalls == true end
        if visuals.panelAutofarm ~= nil then CFG.panelAutofarm = visuals.panelAutofarm == true end
        if visuals.panelRoutes ~= nil then CFG.panelRoutes = visuals.panelRoutes == true end
        if visuals.panelAccount ~= nil then CFG.panelAccount = visuals.panelAccount == true end
        if visuals.panelConfigs ~= nil then CFG.panelConfigs = visuals.panelConfigs == true end
        RT.debugLevel = tonumber(visuals.debugLevel) or RT.debugLevel
    end
    -- Enemy attacks are always highlighted since 2.3.0; an older config that
    -- saved the toggle off must not switch them off.
    RT.renderHazardsEnabled = true

    local streamer = data.streamer
    if type(streamer) == "table" then
        if type(streamer.fields) == "table" then
            for key in pairs(SM.fields) do
                if type(streamer.fields[key]) == "string" then
                    SM.fields[key] = streamer.fields[key]
                end
            end
        end
        SM.vipColor = parseHexColor(streamer.vipColor) or SM.vipColor
        SM.levelColor = parseHexColor(streamer.levelColor) or SM.levelColor
        SM.borderColor = parseHexColor(streamer.borderColor) or SM.borderColor
        if type(streamer.avatarImage) == "string" then
            SM.avatarImage = streamer.avatarImage
        end
        if streamer.autoHideOverlays ~= nil then
            SM.autoHideOverlays = streamer.autoHideOverlays == true
        end

        if type(streamer.binds) == "table" then
            local resolved, missed = 0, 0
            for _, entry in ipairs(streamer.binds) do
                if type(entry) == "table" and type(entry.path) == "string" and SM.targets[entry.field] then
                    local obj = resolveInstancePath(entry.path)
                    if obj then
                        SM.manualBinds[obj] = entry.field
                        resolved = resolved + 1
                    else
                        missed = missed + 1
                    end
                end
            end
            if resolved > 0 or missed > 0 then
                heavyDebug("Config", string.format(
                    "Restored %d manual binds, %d could not be resolved.", resolved, missed))
            end
        end
    end

    if type(data.learnedTelegraphNames) == "table" then
        for _, name in ipairs(data.learnedTelegraphNames) do
            if type(name) == "string" then
                HZ.learnedNames[name] = true
            end
        end
    end

    if type(data.attackBook) == "table" then
        table.clear(HZ.attackBook)
        for _, record in ipairs(data.attackBook) do
            if type(record) == "table" and type(record.name) == "string"
                and type(record.partName) == "string" and tonumber(record.sx) then
                table.insert(HZ.attackBook, record)
            end
        end
        S.invalidateAttackBook()
        if #HZ.attackBook > 0 then
            heavyDebug("Config", string.format("Restored %d attack book entries.", #HZ.attackBook))
        end
    end

    if type(data.ownAttackNames) == "table" then
        local restored = 0
        for _, name in ipairs(data.ownAttackNames) do
            if type(name) == "string" and not HZ.learnedNames[name] then
                HZ.ownNames[name] = true
                restored = restored + 1
            end
        end
        if restored > 0 then
            heavyDebug("Config", string.format("Restored %d own-attack effect names.", restored))
        end
    end

    -- Per-map data (2.4.0), and the pre-2.4 single top-level waypath, which is
    -- adopted into whichever map the config names so an existing setup is not
    -- lost by upgrading.
    table.clear(RT.mapData)
    if type(data.maps) == "table" then
        for code, entry in pairs(data.maps) do
            if MAP_LABELS[code] and type(entry) == "table" then
                RT.mapData[code] = {
                    waypath = type(entry.waypath) == "table" and entry.waypath or {},
                    keep = type(entry.keep) == "table" and entry.keep or {},
                }
                -- Pre-2.7 configs kept the macros inline; adopt them into the
                -- macro store so nothing recorded before the split is lost.
                if type(entry.macros) == "table" and #entry.macros > 0
                    and not RT.macroData[code] then
                    RT.macroData[code] = entry.macros
                end
            end
        end
    end

    if type(data.currentMap) == "string" and MAP_LABELS[data.currentMap] then
        RT.currentMap = data.currentMap
    end

    if type(data.waypath) == "table" and not RT.mapData[RT.currentMap] then
        RT.mapData[RT.currentMap] = { waypath = data.waypath, keep = {} }
        heavyDebug("Config", string.format(
            "Adopted the pre-2.4 waypoint path into map %s.", RT.currentMap))
    end

    loadMacroFile()
    applyMapFromStore(RT.currentMap)
    local mapCount = 0
    for _ in pairs(RT.mapData) do mapCount = mapCount + 1 end
    heavyDebug("Config", string.format("Loaded map %s of %d stored.", RT.currentMap, mapCount))

    return streamer and streamer.enabled == true
end

-- =========================================================================
-- NAMED CONFIGS (2.10.0)
--
-- A saved config is a full snapshot of buildConfigTable() under a name, in its
-- own file. The working config is still DungeonAutofarm_config.json and still
-- autoloads; these are the ones you keep deliberately - a setup per dungeon, a
-- careful one and a reckless one, whatever you like.
-- =========================================================================

local function saveConfigStore()
    if not hasFileAccess() then return false, "no file access in this executor" end
    local ok, err = pcall(function()
        local payload = { version = SCRIPT_VERSION, configs = RT.configs }
        writefile(CFG.configFile, game:GetService("HttpService"):JSONEncode(payload))
    end)
    if ok then
        heavyDebug("Config", string.format("Wrote %d saved config(s) to %s.", #RT.configs, CFG.configFile))
        return true
    end
    heavyDebug("Config", "Config store save failed: " .. tostring(err))
    return false, tostring(err)
end

local function loadConfigStore()
    if not hasFileAccess() then return false end
    local exists = false
    pcall(function() exists = isfile(CFG.configFile) end)
    if not exists then return false end

    local data
    local ok = pcall(function()
        data = game:GetService("HttpService"):JSONDecode(readfile(CFG.configFile))
    end)
    if not ok or type(data) ~= "table" or type(data.configs) ~= "table" then
        heavyDebug("Config", "Config store unreadable; starting with none.")
        return false
    end

    table.clear(RT.configs)
    for _, entry in ipairs(data.configs) do
        if type(entry) == "table" and type(entry.name) == "string" and type(entry.data) == "table" then
            table.insert(RT.configs, {
                name = entry.name,
                savedAt = tonumber(entry.savedAt) or 0,
                data = entry.data,
            })
        end
    end
    heavyDebug("Config", string.format("Loaded %d saved config(s).", #RT.configs))
    return true
end

-- Saving under a name that already exists overwrites it, which is what you
-- want when you are tuning one setup rather than accumulating near-duplicates.
local function saveNamedConfig(name)
    name = tostring(name):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false, "give it a name" end

    local snapshot = { name = name, savedAt = os.time(), data = buildConfigTable() }
    for i, entry in ipairs(RT.configs) do
        if entry.name == name then
            RT.configs[i] = snapshot
            saveConfigStore()
            heavyDebug("Config", string.format("Overwrote saved config '%s'.", name))
            if S.refreshConfigPanel then S.refreshConfigPanel() end
            return true
        end
    end
    table.insert(RT.configs, snapshot)
    saveConfigStore()
    heavyDebug("Config", string.format("Saved config '%s'.", name))
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end

local function loadNamedConfig(index)
    local entry = RT.configs[index]
    if not entry then return false end
    local wantsStreamer = applyConfigData(entry.data)
    heavyDebug("Config", string.format("Loaded saved config '%s'.", entry.name))
    if S.refreshAllWidgets then S.refreshAllWidgets() end
    if S.refreshPathPanel then S.refreshPathPanel() end
    if S.refreshMacroPanel then S.refreshMacroPanel() end
    if S.refreshMapPanel then S.refreshMapPanel() end
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
    return true, wantsStreamer
end

local function deleteNamedConfig(index)
    local entry = table.remove(RT.configs, index)
    if not entry then return false end
    saveConfigStore()
    heavyDebug("Config", string.format("Deleted saved config '%s'.", entry.name))
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end

local function renameNamedConfig(index, name)
    local entry = RT.configs[index]
    if not entry then return false end
    name = tostring(name):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false end
    entry.name = name
    saveConfigStore()
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end

local function loadConfig()
    if not hasFileAccess() then
        return false, "no file access in this executor"
    end

    local exists = false
    pcall(function() exists = isfile(CONFIG_FILE) end)
    if not exists then
        return false, "no saved config yet"
    end

    local data
    local ok, err = pcall(function()
        data = game:GetService("HttpService"):JSONDecode(readfile(CONFIG_FILE))
    end)

    if not ok or type(data) ~= "table" then
        heavyDebug("Config", "Load failed: " .. tostring(err))
        return false, "config file unreadable"
    end

    local wantsStreamer = applyConfigData(data)
    loadConfigStore()
    heavyDebug("Config", "Loaded from " .. CONFIG_FILE)
    return true, wantsStreamer
end

local function syncStreamerToggleWidget()
    if SM.syncToggleWidget then
        pcall(SM.syncToggleWidget)
    end
end

S.loadConfig = loadConfig
S.saveConfig = saveConfig
S.setCurrentMap = setCurrentMap
S.saveNamedConfig = saveNamedConfig
S.loadNamedConfig = loadNamedConfig
S.deleteNamedConfig = deleteNamedConfig
S.renameNamedConfig = renameNamedConfig
S.loadConfigStore = loadConfigStore
S.saveMacroFile = saveMacroFile
S.loadMacroFile = loadMacroFile
S.syncCurrentMapToStore = syncCurrentMapToStore
S.syncStreamerToggleWidget = syncStreamerToggleWidget
end
    end)()
    module(S)
end

-- ===================================== src/ui.lua =====================================
do
    local module = (function()
-- ui.lua - The HUD and the two control windows, built from the kit.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local CFG = S.CFG
local UI = S.UI
local SM = S.SM
local NAV = S.NAV
local HZ = S.HZ
